    /** pdoc search index */const docs = [{"fullname": "broom", "modulename": "broom", "kind": "module", "doc": "<h1 id=\"broom-blind-reconstruction-of-signals-from-observations-in-the-microwaves\">BROOM: Blind Reconstruction Of signals from Observations in the Microwaves</h1>\n\n<p><strong>BROOM</strong> is a Python package for blind component separation and Cosmic Microwave Background (CMB) data analysis.</p>\n\n<hr />\n\n<h2 id=\"installation\">\ud83d\udce6 Installation</h2>\n\n<p>You can install the base package using:</p>\n\n<pre><code>pip install cmbroom\n</code></pre>\n\n<p>This installs the core functionality.<br />\nIf you plan to use the few functions that depend on <code>pymaster</code>, <strong>you must install it separately</strong> (version <code>&gt;=2.4</code>).</p>\n\n<hr />\n\n<h3 id=\"to-include-pymaster-automatically\">\ud83d\udd27 To include <code>pymaster</code> automatically:</h3>\n\n<p>You can install <code>cmbroom</code> along with its optional <code>pymaster</code> dependency by running:</p>\n\n<pre><code>pip install cmbroom[pymaster]\n</code></pre>\n\n<p>However, <code>pymaster</code> requires some additional system libraries to be installed <strong>before</strong> running the above command.</p>\n\n<h4 id=\"on-ubuntudebian\">\u2705 On Ubuntu/Debian:</h4>\n\n<pre><code>sudo apt update\nsudo apt install build-essential python3-dev libfftw3-dev libcfitsio-dev\n</code></pre>\n\n<h4 id=\"on-macos-using-homebrew\">\u2705 On macOS (using Homebrew):</h4>\n\n<pre><code>brew install fftw cfitsio\n</code></pre>\n\n<h2 id=\"documentation\">Documentation</h2>\n\n<p>A detailed introduction to the parameters and simulation pipeline is available in:</p>\n\n<ul>\n<li><a href=\"tutorials/tutorial_satellite.ipynb\"><strong>tutorials/tutorial_satellite.ipynb</strong></a>   </li>\n<li><a href=\"broom/configs/config_demo.yaml\"><strong>configs/config_demo.yaml</strong></a> \u2014 Example configuration file</li>\n</ul>\n\n<p>Component separation methods are covered in:</p>\n\n<ul>\n<li><a href=\"tutorials/tutorial_satellite.ipynb\"><strong>tutorials/tutorial_satellite.ipynb</strong></a> </li>\n<li><a href=\"tutorials/tutorial_satellite_part2.ipynb\"><strong>tutorials/tutorial_satellite_part2.ipynb</strong></a> </li>\n</ul>\n\n<p>Power spectrum estimation is demonstrated in:</p>\n\n<ul>\n<li><a href=\"tutorials/tutorial_spectra.ipynb\"><strong>tutorials/tutorial_spectra.ipynb</strong></a></li>\n</ul>\n\n<p>For partial-sky, ground-based experiment analysis, see:</p>\n\n<ul>\n<li><a href=\"tutorials/tutorial_groundbased.ipynb\"><strong>tutorials/tutorial_groundbased.ipynb</strong></a> </li>\n</ul>\n\n<p>\ud83d\udd17 <strong>Full online documentation:</strong><br />\n\ud83d\udc49 <a href=\"https://alecarones.github.io/broom/\">https://alecarones.github.io/broom/</a></p>\n\n<h2 id=\"references\">References</h2>\n\n<p>Paper on <strong>broom</strong> package is in preparation.</p>\n\n<p>If you use the following methodologies please cite the corresponding papers:</p>\n\n<ul>\n<li>ILC or NILC: <a href=\"https://arxiv.org/abs/astro-ph/0302207\">Bennett et al., 2003</a>, <a href=\"https://arxiv.org/abs/0807.0773\">Delabrouille et al., 2009</a></li>\n<li>cMILC: <a href=\"https://arxiv.org/abs/2006.08628\">Remazeilles et al., 2021</a>, <a href=\"https://arxiv.org/abs/2402.17579\">Carones et al., 2024</a></li>\n<li>MC-ILC or MC-NILC: <a href=\"https://arxiv.org/abs/2212.04456\">Carones et al., 2023</a></li>\n<li>PILC: <a href=\"https://arxiv.org/abs/1601.01515\">Fern\u00e1ndez-Cobos et al., 2016</a></li>\n<li>cPILC: <a href=\"https://arxiv.org/abs/2104.13778\">Adak, 2021</a></li>\n<li>GILC, GNILC, GPILC: <a href=\"https://arxiv.org/abs/1103.1166\">Remazeilles et al., 2011</a>, <a href=\"https://arxiv.org/abs/1605.09387\">Planck Collaboration, 2016</a></li>\n<li>foreground diagnostic: <a href=\"https://arxiv.org/abs/2402.17579\">Carones et al., 2024</a></li>\n<li>power spectrum computation: <a href=\"https://arxiv.org/abs/astro-ph/0409513\">Gorski et al., 2005</a>, <a href=\"https://ui.adsabs.harvard.edu/abs/2019JOSS....4.1298Z/abstract\">Zonca et al., 2019</a>, <a href=\"https://arxiv.org/abs/1809.09603\">Alonso et al., 2019</a></li>\n</ul>\n\n<h3 id=\"dependencies\">\ud83d\udce6 Dependencies</h3>\n\n<p>This package relies on several scientific Python libraries:</p>\n\n<ul>\n<li><a href=\"https://www.astropy.org/\">astropy>=6.0.1</a></li>\n<li><a href=\"https://numpy.org/\">numpy>1.18.5</a></li>\n<li><a href=\"https://scipy.org/\">scipy>=1.8</a></li>\n<li><a href=\"https://healpy.readthedocs.io/\">healpy>=1.15</a></li>\n<li><a href=\"https://pysm3.readthedocs.io/en/latest/#\">pysm3>=3.3.2</a></li>\n<li><a href=\"https://javicarron.github.io/mtneedlet/\">mtneedlet>=0.0.5</a></li>\n</ul>\n"}, {"fullname": "broom.clusters", "modulename": "broom.clusters", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.clusters.get_mcilc_tracers", "modulename": "broom.clusters", "qualname": "get_mcilc_tracers", "kind": "function", "doc": "<p>Generate and save realistic tracer for MC-ILC given the instrumental and parameters configuration.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the instrumental and parameters configuration. \nIt should contain the following attributes:\n<ul>\n<li>experiment : str\nName of the experiment</li>\n<li>lmax : int \nMaximum multipole for the simulations and analysis.      </li>\n<li>lmin : int\nMinimum multipole for the simulations and analysis.</li>\n<li>nside : int\nHEALPix resolution parameter.   </li>\n<li>data_type : str\nType of data to be used in the simulations, either \"maps\" or \"alms\". \nIt also identifies the type of data associated eventually to provided foregrounds and systematics.</li>\n<li>fwhm_out : float\nFull width at half maximum of the output beam in arcminutes used to generate the tracer.</li>\n<li>foreground_models : list\nList of foreground models to be used in the simulations. Used if foregrounds is None.</li>\n<li>real_mc_tracers : dict\nList of dictionaries containing the information about the MC-ILC tracers to be generated.\nIt should contain the following keys:\n<ul>\n<li>channels_tracers: list\nList of channels indexes to be used for the tracers generation. </li>\n<li>path_tracers : str\nPath where the tracers will be saved.</li>\n</ul></li>\n<li>bandpass_integrate : bool\nBoolean indicating whether to integrate over the bandpass of the instrument in the simulations.</li>\n<li>instrument : dict\nInstrument configuration object containing the following attributes:\n<ul>\n<li>channels_tags: list\nList of tags for the instrument channels.</li>\n</ul></li>\n<li>mask_observations : str\nPath to the mask which sets to zero unobserved pixels. If None, no mask is applied.</li>\n<li>coordinates : str\nCoordinate system used for the simulations, either \"G\" for Galactic, \"E\" for Ecliptic, or \"C\" for Celestial.</li>\n<li>pixel_window_in : bool\nBoolean indicating whether to apply the pixel window function to the input data.</li>\n<li>pixel_window_out : str \nBoolean indicating whether to apply the pixel window function to the output tracer.</li>\n<li>verbose : bool\nBoolean indicating whether to print information about the process.</li>\n</ul></li>\n<li><strong>foregrounds</strong> (np.ndarray, optional):\nForegrounds data to be used in the simulations for tracer generation. If None, the foregrounds will be generated using the configuration parameters.\nShape depends on <code>config.data_type</code>:\n<ul>\n<li>If \"maps\": (n_channels, 3, n_pixels) for (T, Q, U)</li>\n<li>If \"alms\": (n_channels, 3, n_alms) for (T, E, B)</li>\n</ul></li>\n<li><strong>systematics</strong> (np.ndarray, optional):\nSystematics data to be added to the simulations for tracer generation. If None, no systematics are added.\nIf provided, it should be a 3D array with shape:</li>\n<li><strong>(n_Shape depends on <code>config.data_type</code>:</strong>: - If \"maps\": (n_channels, 3, n_pixels) for (T, Q, U)\n<ul>\n<li>If \"alms\": (n_channels, 3, n_alms) for (T, E, B)</li>\n</ul></li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments to be passed to healpy 'map2alm' function.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: Saves the generated tracers to the configured output path.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">foregrounds</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">systematics</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">save_inputs</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.initialize_scalar_tracers", "modulename": "broom.clusters", "qualname": "initialize_scalar_tracers", "kind": "function", "doc": "<p>Return the scalar tracers for the MC-ILC component separation run.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the instrumental and parameters configuration. It should contain the following attributes:\n<ul>\n<li><code>nside</code>: HEALPix resolution parameter.</li>\n<li><code>lmax</code>: Maximum multipole for the tracers.</li>\n</ul></li>\n<li><strong>input_alms</strong> (np.ndarray):\nInput foreground alms from which the tracers will be derived if <code>compsep_run[\"mc_type\"]</code> is \"cea_ideal\" or \"rp_ideal\".\nIt should have shape (n_channels, n_alms).</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary containing the information about the component separation run. It should contain the following keys:\n<ul>\n<li><code>mc_type</code>: Type of MC-ILC tracer and partition, either \"cea_ideal\", \"rp_ideal\", \"cea_real\", or \"rp_real\".</li>\n<li><code>domain</code>: Domain where component separation is performed, either \"needlet\" or \"pixel\".</li>\n<li><code>channels_tracers</code>: List of channels indexes to be used for the tracers generation or loading.</li>\n<li><code>path_tracers</code>: Path where the tracers will be loaded from if <code>compsep_run[\"mc_type\"]</code> is \"cea_real\" or \"rp_real\".</li>\n</ul></li>\n<li><strong>field</strong> (str, optional):\nField of the tracers to be loaded or derived, only \"B\" is supported. Default is \"B\".</li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments to be passed to healpy 'map2alm' function.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>tracers</strong> (np.ndarray):\nThe scalar tracers for the MC-ILC component separation run. \nIf compsep_run[\"domain\"] is \"needlet\", it will be a 2D array with alms of the tracers.\nIf compsep_run[\"domain\"] is \"pixel\", it will be a 2D array with maps of the tracers.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">field</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;B&#39;</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_tracers_paths_for_ratio", "modulename": "broom.clusters", "qualname": "get_tracers_paths_for_ratio", "kind": "function", "doc": "<p>Get the paths to the scalar tracers for the MC-ILC component separation run.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the instrumental and parameters configuration. It should contain the following attributes:\n<ul>\n<li><code>nside</code>: HEALPix resolution parameter.</li>\n<li><code>lmax</code>: Maximum multipole for the tracers.</li>\n<li><code>fwhm_out</code>: Full width at half maximum of the output beam in arcminutes associated to the tracers.</li>\n</ul></li>\n<li><strong>path_tracers</strong> (str):\nPath where the tracers are stored. It should be a directory path.</li>\n<li><strong>tracers_tags</strong> (List[str]):\nList of tags for the tracers, corresponding to the frequency channels of the tracers.</li>\n<li><strong>field</strong> (str, optional):\nField of the tracers to be loaded, only \"B\" is supported. Default is \"B\".</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>tracers_paths</strong> (List[str]):\nList of paths to the scalar tracers for the MC-ILC component separation run.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">path_tracers</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">tracers_tags</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">field</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;B&#39;</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.load_scalar_tracers_for_ratio", "modulename": "broom.clusters", "qualname": "load_scalar_tracers_for_ratio", "kind": "function", "doc": "<p>Load the scalar tracers from the specified paths.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>tracers_paths</strong> (List[str]):\nList of paths to the scalar tracers to be loaded.</li>\n<li><strong>nside</strong> (int):\nHEALPix resolution parameter for the tracers.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole for the tracers.</li>\n<li><strong>field</strong> (str, optional):\nField of the tracers to be loaded, only \"B\" is supported. Default is \"B\".</li>\n<li><strong>return_alms</strong> (bool, optional):\nWhether to return the tracers as alms or maps. If True, returns alms; if False, returns maps. Default is True.</li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments to be passed to healpy 'map2alm' function.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>tracers</strong> (np.ndarray):\nThe loaded scalar tracers. If <code>return_alms</code> is True, it will be a 2D array with alms of the tracers.\nIf <code>return_alms</code> is False, it will be a 2D array with maps of the tracers.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">tracers_paths</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nside</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">field</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;B&#39;</span>,</span><span class=\"param\">\t<span class=\"n\">return_alms</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_scalar_tracer_nl", "modulename": "broom.clusters", "qualname": "get_scalar_tracer_nl", "kind": "function", "doc": "<p>Get the scalar MC-ILC ratio tracer in the needlet domain.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>tracers</strong> (np.ndarray):\nThe scalar tracers to be filtered. It can be either a 1D array (single tracer) or a 2D array (multiple tracers).\nIf 2D, the ratio of the first tracer to the second tracer will be returned.</li>\n<li><strong>nside_</strong> (int):\nHEALPix resolution parameter for the tracers.</li>\n<li><strong>lmax_</strong> (int):\nMaximum multipole for the tracers.</li>\n<li><strong>b_ell</strong> (np.ndarray):\nNeedlet filter bandpass function to be applied to the tracers.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: The filtered scalar tracer in the needlet domain.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">tracers</span>, </span><span class=\"param\"><span class=\"n\">nside_</span>, </span><span class=\"param\"><span class=\"n\">lmax_</span>, </span><span class=\"param\"><span class=\"n\">b_ell</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_scalar_tracer", "modulename": "broom.clusters", "qualname": "get_scalar_tracer", "kind": "function", "doc": "<p>Get the scalar MC-ILC ratio tracer in the pixel domain.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>tracers</strong> (np.ndarray):\nThe scalar tracers. It can be either a 1D array (single tracer) or a 2D array (multiple tracers).\nIf 2D, the ratio of the first tracer to the second tracer will be returned.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: The scalar tracer in the pixel domain. If <code>tracers</code> is a 1D array, it returns the tracer as is.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">tracers</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_tracers_compsep", "modulename": "broom.clusters", "qualname": "get_tracers_compsep", "kind": "function", "doc": "<p>Configure component separation methods for obtaining scalar tracers using GILC and needlet domains.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>channels_tracers</strong> (List[int]):\nList of channels indexes associated to the foreground tracers to be used in the component separation.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole for the component separation and analysis.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>List[Dict[str, Any]]</strong>: List of dictionaries containing the configuration for GILC run to obtain the scalar tracers.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">channels_tracers</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span>, </span><span class=\"param\"><span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_mc_config", "modulename": "broom.clusters", "qualname": "get_mc_config", "kind": "function", "doc": "<p>Generate a configuration object for the MC-ILC tracers generation based on the provided configuration.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the instrumental and parameters configuration. \nSee 'generate_and_save_real_tracers' for details.</li>\n<li><strong>tracers_inputs_path</strong> (str):\nPath where the MC-ILC tracers inputs are stored. It should be a directory path.</li>\n<li><strong>save_inputs</strong> (bool, optional):\nWhether to save the simulated input data. Default is False.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Configs</strong>: A new configuration object for the MC-ILC tracers generation, with paths and parameters set according to the provided configuration.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">tracers_inputs_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">save_inputs</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.clusters.get_mc_data", "modulename": "broom.clusters", "qualname": "get_mc_data", "kind": "function", "doc": "<p>Simulate the input data for the MC-ILC tracers generation based on the provided configuration.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config_mc</strong> (Configs):\nConfiguration object for the MC-ILC tracers generation. See 'get_mc_config' for details.</li>\n<li><strong>foregrounds</strong> (SimpleNamespace, optional):\nForegrounds data to be used in the simulations for tracer generation. If None, the foregrounds will be generated using the configuration parameters.</li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments to be passed to healpy 'map2alm' function.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace</strong>: A SimpleNamespace object containing the simulated data for the MC-ILC tracers generation. \nIt will have the following attributes:\n<ul>\n<li><code>total</code>: The total simulated data, which includes CMB, foregrounds, and noise.</li>\n<li><code>cmb</code>: The simulated CMB data.</li>\n<li><code>fgds</code>: The simulated foregrounds data.</li>\n<li><code>noise</code>: The simulated noise data.</li>\n</ul></li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config_mc</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">foregrounds</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">systematics</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Any</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.combine", "modulename": "broom.combine", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.compsep", "modulename": "broom.compsep", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.compsep.get_data_and_compsep", "modulename": "broom.compsep", "qualname": "get_data_and_compsep", "kind": "function", "doc": "<p>Get data and run component separation based on the provided configuration.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with settings for component separation and data handling.\nSee 'component_separation' for details on required attributes.</li>\n<li><strong>foregrounds</strong> (SimpleNamespace, optional):\nForeground data to be used in component separation. \nIt should have the 'total' attribute, a numpy array of shape (n_channels, 3, n_alms/n_pixs)\nwhere 3 correspond to (T, Q, U) if data_type is \"maps\" or (T, E, B) if data_type is \"alms\".\nDefault: None (it will be loaded or generated based on the configuration).</li>\n<li><strong>nsim</strong> (Optional[int or str], optional):\nSimulation number to be used for saving the outputs. If None, the outputs will be saved without label on simulation number.\nDefault: None.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace or None</strong>: If <code>config.return_compsep_products</code> is True, returns outputs. Otherwise returns None.</li>\n</ul>\n\n<h6 id=\"raises\">Raises</h6>\n\n<ul>\n<li><strong>ValueError</strong>: If the configuration is invalid or required fields are missing.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">foregrounds</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.compsep.component_separation", "modulename": "broom.compsep", "qualname": "component_separation", "kind": "function", "doc": "<p>Run component separation methods on input data based on the specified configuration.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the settings for component separation.\nIn particular, it should include the following attributes:\n<ul>\n<li>data_type (str): Type of data, either \"maps\" or \"alms\".</li>\n<li>field_in (str): Field associated to the provided data, e.g. TQU, QU; TEB; EB.</li>\n<li>field_out (str): Fields of the desired outputs from component separation. Default: <code>field_in</code>.</li>\n<li>lmax (int): Desired maximum multipole for the component separation and output products.</li>\n<li>nside (int): Desired HEALPix resolution of the outputs.</li>\n<li>fwhm_out (float): Full width at half maximum of the output maps in arcminutes.</li>\n<li>compsep (Dict[str, Any]): List of dictionaries containing the configuration for each component separation method to be run.</li>\n<li>mask_observations (str): Path to HEALPix mask fits file, if any. Default: None. \nIt is used to exclude unobserved regions in the alm computation and component separation.</li>\n<li>mask_covariance (str): Full path to mask used to weight adn/or exclude pixels in component separation. Default: None.</li>\n<li>leakage_correction (str): Whether to apply EB-leakage correction on input data if 'mask_observations' is provided. Default: None.</li>\n<li>bring_to_common_resolution (bool): Whether to bring the data to a common angular resolution (correcting for input beams). If False, the data will be used as is. Default: True.</li>\n<li>pixel_window_in (bool): Whether pixel window is included in the input data. Default: False.</li>\n<li>pixel_window_out (bool): Whether to include pixel window in the output products. Default: False.</li>\n<li>save_compsep_products (bool): Whether to save the outputs of component separation. Default: True.</li>\n<li>return_compsep_products (bool): Whether to return the outputs of component separation. Default: False.</li>\n<li>path_outputs (str): Path to the directory where the outputs will be saved if 'save_compsep_products' is True. \nIt will save them in \"working_directory/{path_outputs}/{method_specs}\", where {method_specs} is a string containing the method name, domain, and other relevant parameters.\nDefault: Working directory + \"/outputs/\".</li>\n<li>verbose (bool): Whether to print information about the component separation process. Default: False.</li>\n</ul></li>\n<li><strong>data</strong> (SimpleNamespace):\nData object containing the input data for component separation. It should have the following attributes:\n<ul>\n<li><code>total</code>: Total map or alms to be used for component separation.</li>\n<li>Other optional attributes such as <code>noise</code>, <code>cmb</code>, <code>fgds</code>, etc.</li>\n</ul></li>\n<li><strong>nsim</strong> (Optional[int or str], optional):\nSimulation number to be used for saving the outputs. If None, the outputs will be saved without label on simulation number.\nDefault: None.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace or None</strong>: If <code>config.return_compsep_products</code> is True, returns outputs. Otherwise returns None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">data</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.compsep.get_nuisance_covariance", "modulename": "broom.compsep", "qualname": "get_nuisance_covariance", "kind": "function", "doc": "<p>Compute nuisance covariance matrix estimated from simulations.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with settings for nuisance covariance computation. It should include:\n<ul>\n<li>nsim_start (int): Starting simulation number.</li>\n<li>nsims (int): Number of simulations to be used for covariance estimation.</li>\n<li>data_type (str): Type of data, either \"maps\" or \"alms\".</li>\n<li>nside_in (int): HEALPix resolution of the input data.</li>\n<li>lmax_in (int): Maximum multipole of the input data.</li>\n<li>fwhm_out (float): Full width at half maximum of the output maps in arcminutes.</li>\n<li>nside (int): HEALPix resolution of the output covariance.</li>\n<li>lmax (int): Maximum multipole of the output covariance.</li>\n<li>nuisance_covariance (list): List of dictionaries with settings for each nuisance covariance case to be computed. It should contain:\n<ul>\n<li>type (str): Method for covariance computation, either \"scalar\" or \"P_scalar\".</li>\n<li>nuisance (str or list): Nuisance components to be included in the covariance estimation, e.g. \"noise\", \"cmb\", \"fgd\". If not provided, it will include noise and CMB by default.</li>\n<li>Other method-specific parameters.</li>\n</ul></li>\n</ul></li>\n<li><strong>nuisance_path</strong> (str, optional):\nFull path to a directory containing the nuisance data. \nIf None, the nuisance simulations will be simulated based on the configuration.\nDefault: None.</li>\n<li><strong>kwargs</strong> (dict):\nAdditional keywords for map to alm conversion.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: The nuisance covariance matrices are computed and saved based on the configuration.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">config</span>, </span><span class=\"param\"><span class=\"n\">nuisance_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.compsep.nuisance_covariance_serial", "modulename": "broom.compsep", "qualname": "nuisance_covariance_serial", "kind": "function", "doc": "<p>Compute nuisance covariance matrix for a single simulation and update estimation saved in disk.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with settings for nuisance covariance computation. See 'get_nuisance_covariance' for details.</li>\n<li><strong>nsim</strong> (int | str):\nSimulation number or identifier.</li>\n<li><strong>nuisance_path</strong> (str, optional):\nFull path to a directory containing the nuisance data. \nIf None, the nuisance simulations will be simulated based on the configuration.\nDefault: None.</li>\n<li><strong>kwargs</strong> (dict):\nAdditional keywords for map to alm conversion.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: The nuisance covariance matrix for the specified simulation is computed and used to update the estimation saved in disk.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nuisance_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.compsep.estimate_residuals", "modulename": "broom.compsep", "qualname": "estimate_residuals", "kind": "function", "doc": "<p>Estimate residual foregrounds from component-separated maps.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with settings for component separation. It should include:\n<ul>\n<li>mask_observations (str): Full path to HEALPix mask fits file, if any. Default: None.\nIt is used to exclude unobserved regions from loaded foreground tracers.</li>\n<li>mask_covariance (str): Full path to mask used to weight pixels in component separation.</li>\n<li>field_out (str): Fields of the desired outputs for residuals estimate. Default: <code>config.field_in</code>.</li>\n<li>compsep_residuals (list): List of dictionaries with settings for each component separation method to estimate residuals. It should contain:\n<ul>\n<li>compsep_path (str): Path to the directory containing the 'weights' folder of corresponding component separation method.\nWeights will be loaded from \"working_directory/{compsep_path}/weights. </li>\n<li>gilc_path (str): Path to the directory containing the GILC maps to be used as multifrequency foreground tracers.\nTracers will be loaded from \"working_directory/{gilc_path}/output_total\".</li>\n<li>gilc_components (list): List of strings indicating the GILC output components to be propagated through the component separation weights.</li>\n<li>field_in (str): Fields of the data to be loaded. Optional, default is <code>config.field_out</code>.</li>\n</ul></li>\n<li>lmax (int): Maximum multipole for output products.</li>\n<li>nside (int): HEALPix resolution associated to GNILC tracers and component separation weights.</li>\n<li>fwhm_out (float): Full width at half maximum associated to GNILC tracer and component separation products.</li>\n<li>pixel_window_out (bool): Whether to include pixel window in the output products. Default: False.</li>\n<li>return_compsep_products (bool): Whether to return the residuals estimate. Default: False.</li>\n<li>save_compsep_products (bool): Whether to save the residuals estimate. Default: True.</li>\n<li>verbose (bool): Whether to print information about the residuals estimate. Default: False.</li>\n</ul></li>\n<li><strong>nsim</strong> (int | str | None):\nSimulation number or identifier.</li>\n<li><strong>gilc_outputs</strong> (SimpleNamespace, optional):\nIf provided, it should contain the GILC outputs to be used as foreground tracers in the residual estimation. \nIf None, the GILC outputs will be loaded from disk based on the paths specified in <code>compsep_residuals</code>.\nDefault: None.</li>\n<li>**<strong>kwargs</strong>: Additional keyword arguments for internal helper functions.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace Residual products if <code>config.return_compsep_products</code> is True, otherwise None.</strong></li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">gilc_outputs</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.compsep.combine_with_weights", "modulename": "broom.compsep", "qualname": "combine_with_weights", "kind": "function", "doc": "<p>Propagate input data through component separation weights.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing the settings for component separation.\nIn particular, it should include the following attributes:\n<ul>\n<li>data_type (str): Type of data, either \"maps\" or \"alms\".</li>\n<li>field_in (str): Field associated to the provided data, e.g. TQU, QU; TEB; EB.</li>\n<li>field_out (str): Fields of the desired outputs from component separation. Default: <code>field_in</code>.</li>\n<li>lmax (int): Maximum multipole considered in the component separation and for output products.</li>\n<li>nside (int): HEALPix resolution associated to component separation weights and output products.</li>\n<li>fwhm_out (float): Full width at half maximum at which component separation weights and output products are defined, in arcminutes.</li>\n<li>compsep (Dict[str, Any]): List of dictionaries containing the configuration for each component separation method to be run.</li>\n<li>mask_observations (str): Path to HEALPix mask fits file, if any. Default: None. \nIt is used to exclude unobserved regions in the alm computation.</li>\n<li>mask_covariance (str): Full path to mask used to weight and/or exclude pixels in component separation. Default: None.</li>\n<li>leakage_correction (str): Whether to apply EB-leakage correction on input data if 'mask_observations' is provided. Default: None.</li>\n<li>bring_to_common_resolution (bool): Whether to bring the data to a common angular resolution (correcting for input beams). If False, the data will be used as is. Default: True.</li>\n<li>pixel_window_in (bool): Whether pixel window is included in the input data. Default: False.</li>\n<li>pixel_window_out (bool): Whether to include pixel window in the output products. Default: False.</li>\n<li>save_compsep_products (bool): Whether to save the combined outputs. Default: True.</li>\n<li>return_compsep_products (bool): Whether to return the combined outputs. Default: False.</li>\n<li>verbose (bool): Whether to print information about the component separation process. Default: False.</li>\n<li>compsep_propagate (list): List of dictionaries with settings for each component separation combination to be performed. It should contain:\n<ul>\n<li>compsep_path (str): Path to the directory containing the 'weights' folder of corresponding component separation method.\nWeights will be loaded from \"working_directory/{compsep_path}/weights.</li>\n</ul></li>\n</ul></li>\n<li><strong>data</strong> (SimpleNamespace):\nData object containing the input data to be propagated through the component separation weights.</li>\n<li><strong>nsim</strong> (Optional[int or str], optional):\nSimulation number to be used for saving the outputs. If None, the outputs will be saved without label on simulation number.\nDefault: None.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace or None</strong>: If <code>config.return_compsep_products</code> is True, returns outputs. Otherwise returns None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">data</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations", "modulename": "broom.configurations", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.join", "modulename": "broom.configurations", "qualname": "join", "kind": "function", "doc": "<p>Custom YAML tag to join sequences into a single string.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>loader</strong> (yaml.Loader):\nThe YAML loader instance.</li>\n<li><strong>node</strong> (yaml.Node):\nThe YAML node to process.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>str</strong>: A string formed by joining the sequence elements.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">loader</span><span class=\"p\">:</span> <span class=\"n\">yaml</span><span class=\"o\">.</span><span class=\"n\">loader</span><span class=\"o\">.</span><span class=\"n\">Loader</span>, </span><span class=\"param\"><span class=\"n\">node</span><span class=\"p\">:</span> <span class=\"n\">yaml</span><span class=\"o\">.</span><span class=\"n\">nodes</span><span class=\"o\">.</span><span class=\"n\">Node</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.parse_args", "modulename": "broom.configurations", "qualname": "parse_args", "kind": "function", "doc": "<p>Parse command-line arguments, especially the configuration file path.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>None</strong></li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>argparse.Namespace</strong>: The parsed arguments.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"return-annotation\">) -> <span class=\"n\">argparse</span><span class=\"o\">.</span><span class=\"n\">Namespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.get_params", "modulename": "broom.configurations", "qualname": "get_params", "kind": "function", "doc": "<p>Get parameters from a YAML configuration file.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config_path</strong> (str, optional):\nPath to the configuration file. If not provided, uses the default path.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Configs</strong>: An instance of the Configs class containing the configuration parameters.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">config_path</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.InstrumentConfig", "modulename": "broom.configurations", "qualname": "InstrumentConfig", "kind": "class", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.frequency", "modulename": "broom.configurations", "qualname": "InstrumentConfig.frequency", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.depth_I", "modulename": "broom.configurations", "qualname": "InstrumentConfig.depth_I", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.depth_P", "modulename": "broom.configurations", "qualname": "InstrumentConfig.depth_P", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.fwhm", "modulename": "broom.configurations", "qualname": "InstrumentConfig.fwhm", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.bandwidth", "modulename": "broom.configurations", "qualname": "InstrumentConfig.bandwidth", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.ell_knee", "modulename": "broom.configurations", "qualname": "InstrumentConfig.ell_knee", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.alpha_knee", "modulename": "broom.configurations", "qualname": "InstrumentConfig.alpha_knee", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.channels_tags", "modulename": "broom.configurations", "qualname": "InstrumentConfig.channels_tags", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.path_bandpasses", "modulename": "broom.configurations", "qualname": "InstrumentConfig.path_bandpasses", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.path_hits_maps", "modulename": "broom.configurations", "qualname": "InstrumentConfig.path_hits_maps", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.path_depth_maps", "modulename": "broom.configurations", "qualname": "InstrumentConfig.path_depth_maps", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.path_beams", "modulename": "broom.configurations", "qualname": "InstrumentConfig.path_beams", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.beams", "modulename": "broom.configurations", "qualname": "InstrumentConfig.beams", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.configurations.InstrumentConfig.reset_attributes", "modulename": "broom.configurations", "qualname": "InstrumentConfig.reset_attributes", "kind": "function", "doc": "<p>Reset all attributes to their default values.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.InstrumentConfig.remove_none_attributes", "modulename": "broom.configurations", "qualname": "InstrumentConfig.remove_none_attributes", "kind": "function", "doc": "<p>Remove attributes that are set to None.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.InstrumentConfig.load_from_yaml", "modulename": "broom.configurations", "qualname": "InstrumentConfig.load_from_yaml", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">yaml_data</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>, </span><span class=\"param\"><span class=\"n\">experiment</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.InstrumentConfig.load_from_config", "modulename": "broom.configurations", "qualname": "InstrumentConfig.load_from_config", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">config_data</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.configurations.Configs", "modulename": "broom.configurations", "qualname": "Configs", "kind": "class", "doc": "<p>Class to store settings and relevant quantities for the main script.</p>\n"}, {"fullname": "broom.configurations.Configs.__init__", "modulename": "broom.configurations", "qualname": "Configs.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config_path</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]]</span> <span class=\"o\">=</span> <span class=\"o\">&lt;</span><span class=\"n\">factory</span><span class=\"o\">&gt;</span></span>)</span>"}, {"fullname": "broom.configurations.Configs.config_path", "modulename": "broom.configurations", "qualname": "Configs.config_path", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[str]", "default_value": "None"}, {"fullname": "broom.configurations.Configs.config", "modulename": "broom.configurations", "qualname": "Configs.config", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[Dict[str, Any]]"}, {"fullname": "broom.configurations.Configs.to_dict_for_mc", "modulename": "broom.configurations", "qualname": "Configs.to_dict_for_mc", "kind": "function", "doc": "<p>Extract relevant attributes as a dictionary.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gilcs", "modulename": "broom.gilcs", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.gilcs.gilc", "modulename": "broom.gilcs", "qualname": "gilc", "kind": "function", "doc": "<p>Performs Generalized Internal Linear Combination (GILC) component separation on scalar fields.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with general settings. It includes:\n    - lmax : int, maximum multipole for the component separation.\n    - nside : int, HEALPix resolution parameter for compsep products.\n    - fwhm_out : float, full width at half maximum of the output beam in arcminutes.\n    - pixel_window_out : bool, whether to apply a pixel window to the output maps.\n    - field_out : str, desired output fields (e.g., \"T\", \"E\", \"B\", \"QU\", \"TQU\", \"QU_E\", \"QU_B\").\n    - save_compsep_products : bool, whether to save component separation products.\n    - return_compsep_products : bool, whether to return component separation products.\n    - path_outputs : str, path to save the output files.</li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nInput multifrequency alms of the scalar fields. \nEach attribute should be a numpy array of shape (n_channels, (n_fields), n_alms, n_components), of the noise maps. \nwith n_fields &gt; 1 if multiple scalars are provided.\nIt should contain:\n<ul>\n<li>total : np.ndarray, alms of the total input maps.</li>\n<li>nuisance : Optional[np.ndarray], alms of the nuisance maps (if available).\nAlternatively to nuisance, it can contain:</li>\n<li>cmb : np.ndarray, alms of the CMB maps.</li>\n<li>noise : np.ndarray, alms of the noise maps.</li>\n</ul></li>\n<li><strong>compsep_run</strong> (Dict[str, Any]):\nDictionary with component separation parameters. It should include:\n<ul>\n<li>domain : str, either \"pixel\" or \"needlet\" for the component separation domain.</li>\n<li>channels_out : list, indices of the frequency channels to reconstruct with GILC. Default is all channels.</li>\n<li>depro_cmb : Optional[Union[float, list, np.ndarray]], deprojection factor for CMB (scalar or list per needlet bands). \nDefault is None.</li>\n<li>m_bias : Optional[Union[float, list, np.ndarray]], if not zero, it will include m_bias more (if m_bias &gt; 0) \nor less (if m_bias &lt; 0) modes in the reconstructed GNILC maps. Default is 0.\nIt can be a list if different values are needed for different needlet bands.</li>\n<li>nuisance : Union[str, List[str]], name or list of names of the nuisance components to be used for the nuisance covariance.</li>\n<li>needlet_config: Dictionary containing needlet settings. Needed if domain is \"needlet\". It should include:\n<ul>\n<li>\"needlet_windows\": Type of needlet windows ('cosine', 'standard', 'mexican').</li>\n<li>\"ell_peaks\": List of integers defining multipoles of peaks for needlet bands (required for 'cosine').</li>\n<li>\"width\": Width of the needlet windows (required for 'standard' and 'mexican').</li>\n<li>\"merging_needlets\": Integer or list of integers defining ranges of needlets to be merged.</li>\n</ul></li>\n<li>b_squared : bool, whether to square the needlet windows. Default is False.            </li>\n<li>adapt_nside : bool, whether to adapt the nside based on the needlet windows. Default is False.</li>\n<li>mask : Optional[np.ndarray], mask to apply to the maps (if available).</li>\n<li>cov_noise_debias : Optional[Union[float, list, np.ndarray]],\nIf not zero, it will debias the covariances by subtracting a term cov_noise_debias * noise_covariance.\nIt can be a scalar or a list per needlet bands. Default is 0.</li>\n</ul></li>\n<li>**<strong>kwargs</strong> ():\nDictionary of additional keyword arguments to pass to healpy function 'map2alm'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Optional[SimpleNamespace]</strong> ():\nOutput map object with reconstructed foreground maps if config.return_compsep_products is True.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gilcs.fgd_diagnostic", "modulename": "broom.gilcs", "qualname": "fgd_diagnostic", "kind": "function", "doc": "<p>Return diagnostic maps of the foreground complexity for the provided scalar fields.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with general settings. It includes:\n    - lmax : int, maximum multipole for the component separation.\n    - nside : int, HEALPix resolution parameter for compsep products.\n    - fwhm_out : float, full width at half maximum of the output beam in arcminutes.\n    - field_out : str, desired fields to be considered (e.g., \"T\", \"E\", \"B\", \"TEB\").\n    - save_compsep_products : bool, whether to save diagnostic maps.\n    - return_compsep_products : bool, whether to return diagnostic maps.\n    - path_outputs : str, path to save the output files.</li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nInput multifrequency alms of the scalar fields. \nEach attribute should be a numpy array of shape (n_channels, (n_fields), n_alms, n_components), \nwith n_fields &gt; 1 if multiple scalars are provided.\nIt should contain:\n<ul>\n<li>total : np.ndarray, alms of the total input maps.</li>\n<li>nuisance : Optional[np.ndarray], alms of the nuisance maps (if available).\nAlternatively to nuisance, it can contain:</li>\n<li>cmb : np.ndarray, alms of the CMB maps.</li>\n<li>noise : np.ndarray, alms of the noise maps.</li>\n</ul></li>\n<li><strong>compsep_run</strong> (Dict[str, Any]):\nDictionary with diagnostic parameters. It should include:\n    - domain : str, either \"pixel\" or \"needlet\" for the component separation domain.\n    - nuisance : Union[str, List[str]], name or list of names of the nuisance components to be used for the nuisance covariance.\n                Default is [\"noise\", \"cmb\"].\n    - needlet_config: Dictionary containing needlet settings. Needed if domain is \"needlet\". It should include:\n        - \"needlet_windows\": Type of needlet windows ('cosine', 'standard', 'mexican').\n        - \"ell_peaks\": List of integers defining multipoles of peaks for needlet bands (required for 'cosine').\n        - \"width\": Width of the needlet windows (required for 'standard' and 'mexican').\n        - \"merging_needlets\": Integer or list of integers defining ranges of needlets to be merged.\n    - b_squared : bool, whether to square the needlet windows. Default is False.<br />\n    - adapt_nside : bool, whether to adapt the nside based on the needlet windows. Default is False.\n    - mask : Optional[np.ndarray], mask to apply to the maps (if available).</li>\n<li>**<strong>kwargs</strong> ():\nDictionary of additional keyword arguments to pass to healpy function 'map2alm'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Optional[SimpleNamespace]</strong>: Object containing foreground diagnostic maps.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gilcs.get_nuisance_idx", "modulename": "broom.gilcs", "qualname": "get_nuisance_idx", "kind": "function", "doc": "<p>Determines the index or indices of nuisance alms based on the input alms object and component separation parameters.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>input_attrs</strong> (List[str]):\nList of attribute names in the input_alms object.</li>\n<li><strong>compsep_run</strong> (Dict[str, Any]):\nComponent separation parameters including 'nuisance'.</li>\n<li><strong>verbose</strong> (bool, optional):\nIf True, prints additional information about the nuisance alms being used. Default is False.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Union[int, List[int]]</strong>: Index or list of indices for nuisance alms.</li>\n</ul>\n\n<h6 id=\"raises\">Raises</h6>\n\n<p>ValueError\n    If the input_alms object does not have the required attributes for nuisance covariance.</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">input_attrs</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">verbose</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gilcs.compute_and_update_nuisance_covariance", "modulename": "broom.gilcs", "qualname": "compute_and_update_nuisance_covariance", "kind": "function", "doc": "<p>Computes the nuisance covariance matrix and updates the stored estimate in disk.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with general settings.</li>\n<li><strong>nuis_alms</strong> (np.ndarray):\nNuisance alms array of shape (n_channels, (n_fields), n_alms).</li>\n<li><strong>nuis_case</strong> (Dict[str, Any]):\nDictionary with nuisance covariance parameters.</li>\n<li><strong>nsim</strong> (Optional[Union[int, str]]):\nSimulation number identifier for covariance estimation.</li>\n<li>**<strong>kwargs:</strong>: Additional keyword arguments for alm/map conversions.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong></li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">nuis_alms</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">nuis_case</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gilcs.Cn_C_Cn", "modulename": "broom.gilcs", "qualname": "Cn_C_Cn", "kind": "function", "doc": "<p>Whiten the signal covariance with nuisance and perform SVD.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>C</strong> (np.ndarray):\nSignal covariance matrix. Shape should be (n_channels, n_channels) or (npix, n_channels, n_channels).</li>\n<li><strong>C_n</strong> (np.ndarray):\nNuisance covariance matrix. Shape should be (n_channels, n_channels) or (npix, n_channels, n_channels).</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>tuple[np.ndarray, np.ndarray]</strong>: Tuple of eigenvalues and eigenvectors.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">C</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">C_n</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gpilcs", "modulename": "broom.gpilcs", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.gpilcs.gpilc", "modulename": "broom.gpilcs", "qualname": "gpilc", "kind": "function", "doc": "<p>Perform Generalized Polarization Internal Linear Combination (GP(R)ILC) on input spherical harmonics \nto reconstruct Galactic emission at the observed microwave frequencies.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing settings for the GP(R)ILC run. It should include:\n    - lmax : int, maximum multipole for the component separation.\n    - nside : int, HEALPix resolution parameter for compsep products.\n    - fwhm_out : float, full width at half maximum of the output beam in arcminutes.\n    - pixel_window_out : bool, whether to apply a pixel window to the output maps.\n    - field_out : str, desired output fields (e.g., \"E\", \"B\", \"QU\", \"EB\", \"QU_E\", \"QU_B\").\n    - save_compsep_products : bool, whether to save component separation products.\n    - return_compsep_products : bool, whether to return component separation products.\n    - path_outputs : str, path to save the output files.\n    - leakage_correction : str, type of leakage correction to apply (e.g., \"recycling\", \"purify\").</li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nInput multifrequency alms associated to polarization. \nEach attribute should be a numpy array of shape (n_channels, 2, n_alms, n_components),\nif both E- and B-modes are provided, (n_channels, n_alms, n_components) otherwise.\nIt should contain:\n<ul>\n<li>total : np.ndarray, alms of the total input maps.</li>\n<li>nuisance : Optional[np.ndarray], alms of the nuisance maps (if available).\nAlternatively to nuisance, it can contain:</li>\n<li>cmb : np.ndarray, alms of the CMB maps.</li>\n<li>noise : np.ndarray, alms of the noise maps.</li>\n</ul></li>\n<li><strong>compsep_run</strong> (Dict[str, Any]):\nDictionary with component separation parameters. It should include:\n<ul>\n<li>domain : str, either \"pixel\" or \"needlet\" for the component separation domain.</li>\n<li>channels_out : list, indices of the frequency channels to reconstruct with GILC. Default is all channels.</li>\n<li>depro_cmb : Optional[Union[float, list, np.ndarray]], deprojection factor for CMB (scalar or per needlet band). \nDefault is None.</li>\n<li>m_bias : Optional[Union[float, list, np.ndarray]], if not zero, it will include m_bias more (if m_bias &gt; 0) \nor less (if m_bias &lt; 0) modes in the reconstructed GPILC maps. Default is 0.\nIt can be a list if different values are needed for different needlet bands.</li>\n<li>nuisance : List[str] or str, components to include in the nuisance covariance. Default is [\"noise\", \"cmb\"].</li>\n<li>needlet_config: Dictionary containing needlet settings. Needed if domain is \"needlet\". It should include:\n<ul>\n<li>\"needlet_windows\": Type of needlet windows ('cosine', 'standard', 'mexican').</li>\n<li>\"ell_peaks\": List of integers defining multipoles of peaks for needlet bands (required for 'cosine').</li>\n<li>\"width\": Width of the needlet windows (required for 'standard' and 'mexican').</li>\n<li>\"merging_needlets\": Integer or list of integers defining ranges of needlets to be merged.</li>\n</ul></li>\n<li>mask : Optional[np.ndarray], mask to apply to the maps (if available).</li>\n<li>cov_noise_debias : Optional[Union[float, list, np.ndarray]], noise covariance debiasing factor.\nIf set to a non-zero value, it will subtract a 'noise_debias' fraction of noise covariance \nfrom the input and nuisance covariance matrices.</li>\n</ul></li>\n<li>**<strong>kwargs</strong> ():\nDictionary of additional keyword arguments to pass to healpy function 'map2alm'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Optional[SimpleNamespace]</strong>: Output object with component-separated maps, if config.return_compsep_products is True.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gpilcs.fgd_P_diagnostic", "modulename": "broom.gpilcs", "qualname": "fgd_P_diagnostic", "kind": "function", "doc": "<p>Perform foreground diagnostic for polarization (P) on input spherical harmonic coefficients (alms).</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with general settings. It includes:\n    - lmax : int, maximum multipole for the component separation.\n    - nside : int, HEALPix resolution parameter for compsep products.\n    - fwhm_out : float, full width at half maximum of the output beam in arcminutes.\n    - field_out : str, desired fields to be considered (e.g., \"T\", \"E\", \"B\", \"TEB\").\n    - save_compsep_products : bool, whether to save diagnostic maps.\n    - return_compsep_products : bool, whether to return diagnostic maps.\n    - path_outputs : str, path to save the output files.</li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nInput multifrequency alms of polarization fields.\nEach attribute should be a numpy array of shape (n_channels, 2, n_alms, n_components),\nif both E- and B-modes are provided, (n_channels, n_alms, n_components) otherwise.\nIt should contain:\n<ul>\n<li>total : np.ndarray, alms of the total input maps.</li>\n<li>nuisance : Optional[np.ndarray], alms of the nuisance maps (if available).\nAlternatively to nuisance, it can contain:</li>\n<li>cmb : np.ndarray, alms of the CMB maps.</li>\n<li>noise : np.ndarray, alms of the noise maps.</li>\n</ul></li>\n<li><strong>compsep_run</strong> (Dict[str, Any]):\nDictionary with diagnostic parameters. It should include:\n    - domain : str, either \"pixel\" or \"needlet\" for the component separation domain.\n    - nuisance : List[str] or str, components to include in the nuisance covariance. Default is [\"noise\", \"cmb\"].\n    - needlet_config: Dictionary containing needlet settings. Needed if domain is \"needlet\". It should include:\n        - \"needlet_windows\": Type of needlet windows ('cosine', 'standard', 'mexican').\n        - \"ell_peaks\": List of integers defining multipoles of peaks for needlet bands (required for 'cosine').\n        - \"width\": Width of the needlet windows (required for 'standard' and 'mexican').\n        - \"merging_needlets\": Integer or list of integers defining ranges of needlets to be merged.\n    - adapt_nside : bool, whether to adapt the nside based on the needlet windows. Default is False.\n    - mask : Optional[np.ndarray], mask to apply to the maps (if available).\n    - cov_noise_debias : Optional[Union[float, list, np.ndarray]], noise covariance debiasing factor.</li>\n<li>**<strong>kwargs</strong> ():\nDictionary of additional keyword arguments to pass to healpy function 'map2alm'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Optional[SimpleNamespace]</strong>: Object containing foreground diagnostic maps.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.gpilcs.compute_and_update_nuisance_P_covariance", "modulename": "broom.gpilcs", "qualname": "compute_and_update_nuisance_P_covariance", "kind": "function", "doc": "<p>Computes the nuisance covariance matrix for GP(R)ILC and updates the stored estimate in disk.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object with general settings.</li>\n<li><strong>nuis_alms</strong> (np.ndarray):\nNuisance alms array of shape (n_channels, (n_fields), n_alms).</li>\n<li><strong>nuis_case</strong> (Dict[str, Any]):\nDictionary with GP(R)ILC nuisance covariance parameters.</li>\n<li><strong>nsim</strong> (Optional[Union[int, str]]):\nSimulation number identifier for covariance estimation.</li>\n<li>**<strong>kwargs:</strong>: Additional keyword arguments for alm/map conversions.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong></li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">nuis_alms</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">nuis_case</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs", "modulename": "broom.ilcs", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.ilcs.ilc", "modulename": "broom.ilcs", "qualname": "ilc", "kind": "function", "doc": "<p>Perform Internal Linear Combination (ILC) component separation (all its variants) on CMB scalar fields.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing global settings. It includes:\n<ul>\n<li>lmax : int, maximum multipole for the component separation.</li>\n<li>nside : int, HEALPix resolution parameter for compsep products.</li>\n<li>fwhm_out : float, full width at half maximum of the output beam in arcminutes.</li>\n<li>pixel_window_out : bool, whether to apply a pixel window to the output maps.</li>\n<li>field_out : str, desired output fields (e.g., \"T\", \"E\", \"B\", \"QU\", \"TQU\", \"QU_E\", \"QU_B\").</li>\n<li>save_compsep_products : bool, whether to save component separation products.</li>\n<li>return_compsep_products : bool, whether to return component separation products.</li>\n<li>path_outputs : str, path to save the output files.</li>\n<li>units : str, units of the output maps (e.g., \"uK_CMB\"). Used to compute components SEDs, if needed.</li>\n<li>bandpass_integrate : bool, whether inputs are bandpass-integrated. Used to compute components SEDs, if needed.</li>\n</ul></li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nSimpleNamespace object containing input spherical harmonic coefficients (alms). \nEach attribute has shape (n_channels, (n_fields), n_alms), where n_fields depend on the fields requested in config.field_out.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary specifying component separation parameters. It includes:\n<ul>\n<li>\"method\": Method to use for component separation (e.g., \"ilc\", \"cilc\", \"mc_ilc\").</li>\n<li>\"domain\": Domain of the component separation (e.g., \"pixel\", \"needlet\").</li>\n<li>\"needlet_config\": Dictionary containing needlet settings:\n<ul>\n<li>\"needlet_windows\": Type of needlet windows ('cosine', 'standard', 'mexican').</li>\n<li>\"ell_peaks\": List of integers defining multipoles of peaks for needlet bands (required for 'cosine').</li>\n<li>\"width\": Width of the needlet windows (required for 'standard' and 'mexican').</li>\n<li>\"merging_needlets\": Integer or list of integers defining ranges of needlets to be merged.</li>\n</ul></li>\n<li>\"ilc_bias\": Parameter setting the residual percentage ILC bias (default is 0. and covariance will be computed over the whole sky).</li>\n<li>\"reduce_ilc_bias\": Boolean. If True, it implements a procedure to attenuate ILC bias.</li>\n<li>\"b_squared\": Boolean indicating if the needlet windows should be squared (if domain is \"needlet\").</li>\n<li>\"adapt_nside\": Adapt HEALPix resolution of needlet maps to sampled multipole range. Deafult: False.</li>\n<li>\"save_needlets\": boolean. Whether to save adopted needlet bands in the output directory. \nIf not provided, it is set to the value of config.save_compsep_products. Default: True.</li>\n<li>\"save_weights\": boolean. Whether to save compsep weights maps in the output directory.\nIf not provided, it is set to the value of config.save_compsep_products. Default: True.</li>\n<li>\"mask\": (optional) HEALPix mask which will exclude (unobserved) regions from covariance computation. \nIt must be a 1D array with shape (12 * nside**2,). If non-binary, it will be used to weigh pixel in covariance computation.</li>\n<li>\"path_patches\": (str) Path to .npy file containing pre-defined patches for MC-ILC. If not provided, patches will be defined on the fly. Default: None.</li>\n<li>\"n_patches\": (int) Number of patches to use in MC-ILC. Default: 50.</li>\n<li>\"mc_type\": (str), needed if method is \"mcilc\" or \"mc_ilc\".\nType of MC-ILC to use. Options: \"cea_ideal\", \"rp_ideal\", \"cea_real\", \"rp_real\". Default: \"cea_real\".</li>\n<li>\"cov_noise_debias\": (float, list) Noise covariance debiasing factor. \nIf different from 0. it will debias the covariance matrix by a factor cov_noise_debias * noise_covariance.\nIt must be a list with the same length as the number of needlet scales if domain is \"needlet\", otherwise a single float.</li>\n<li>\"special_nls\": (list) List of needlet scales where moment deprojection is applied in c_ilc and clustering in mc_ilc.</li>\n<li>\"constraints\": Dictionary to be used if method is \"cilc\" or \"c_ilc\". It must contain:\n<ul>\n<li>\"components\": list of strings with components to be deprojected in cILC. It can be a list of lists if domain is \"needlet\".\nEach list will be associated to a needlet band in order.\nOptionally can include:</li>\n<li>\"beta_d\": (float, list): dust spectral index to compute dust moments. If list, a different beta_d is used for each needlet band. Default: 1.54.</li>\n<li>\"T_d\": (float, list): dust temperature to compute dust moments. If list, a different T_d is used for each needlet band. Default: 19.6.</li>\n<li>\"beta_s\": (float, list): synchrotron spectral index to compute synchrotron moments. If list, a different beta_s is used for each needlet band. Default: -3.</li>\n<li>\"deprojection\": (float, list): deprojection factor for each moment. If list, a different deprojection factor is used for each moment.\nIt can be a list of lists if domain is \"needlet\". Each list will be associated to a needlet band in order. Default: 0. (i.e. full deprojection) for each moment and each needlet band.</li>\n</ul></li>\n</ul></li>\n<li>**<strong>kwargs</strong> (dict):\nAdditional keyword arguments forwarded to hp.map2alm.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>outputs</strong> (SimpleNamespace or None):\nOutput separated components as a SimpleNamespace object if \nconfig.return_compsep_products is True; otherwise None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs.get_ilc_weights", "modulename": "broom.ilcs", "qualname": "get_ilc_weights", "kind": "function", "doc": "<p>Compute Internal Linear Combination (ILC) weights for a given spectral component (typically CMB).</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>A_out</strong> (np.ndarray):\nSpectral response vector of the target component (e.g., CMB), shape (n_channels,).</li>\n<li><strong>inv_cov</strong> (np.ndarray):\nInverse of the covariance matrix. Can be 2D or 3D depending on bias settings.</li>\n<li><strong>input_shapes</strong> (tuple):\nShape of the input map, used to reshape or broadcast weights.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary specifying component separation settings, including:\n<ul>\n<li>'A': Optional constraint matrix for deprojection of additional components. Shape (n_components, n_channels).</li>\n<li>'e': Deprojection vector. Shape (n_components,).</li>\n<li>'ilc_bias': Flag indicating if covariance is pixel-independent (0.0) or not.</li>\n</ul></li>\n<li><strong>mask_cov</strong> (np.ndarray, optional):\nOptional mask used in covariance computation, shape (n_pixels,).</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: ILC weights with shape (n_channels, n_pixels) if ilc_bias is not 0.0,\notherwise (n_channels,).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">A_out</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">inv_cov</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">input_shapes</span><span class=\"p\">:</span> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">mask_cov</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs.get_mcilc_weights", "modulename": "broom.ilcs", "qualname": "get_mcilc_weights", "kind": "function", "doc": "<p>Compute weights for the MC-ILC method over spatial patches.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>inputs</strong> (np.ndarray):\nInput sky maps, shape (n_channels, n_pixels).</li>\n<li><strong>patches</strong> (np.ndarray):\nInteger labels assigning each pixel to a spatial patch.</li>\n<li><strong>A_cmb</strong> (np.ndarray):\nSpectral response of the CMB component, shape (n_channels,).</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary with MCILC options, including optional constraints and bias reduction. See 'ilc' for details.</li>\n<li><strong>mask_mcilc</strong> (np.ndarray, optional):\nMask to include/exclude pixels in covariance computation. If None, all pixels are used.\nIf not binary, it will be used to weigh pixels in covariance computation.</li>\n<li><strong>inputs_2</strong> (np.ndarray, optional):\nOptional second set of input maps for cross-covariance computation.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: MCILC weights for each pixel, shape (n_channels, n_pixels).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">inputs</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">patches</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">A_cmb</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">mask_mcilc</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">inputs_2</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs.get_ilc_cov", "modulename": "broom.ilcs", "qualname": "get_ilc_cov", "kind": "function", "doc": "<p>Compute the input covariance matrix for ILC.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>input_maps</strong> (np.ndarray):\nInput sky maps, shape (n_channels, n_pixels).</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary controlling ILC behavior (bias flags, mask, etc.). See 'ilc' for details.</li>\n<li><strong>fwhm_out</strong> (float):\nOutput beam full-width at half-maximum (FWHM) in arcminutes.</li>\n<li><strong>b_ell</strong> (np.ndarray):\nNeedlet harmonic window function, if applicable.</li>\n<li><strong>mask</strong> (np.ndarray, optional):\nMask to exclude and/or weight pixels in covariance computation.</li>\n<li><strong>input_maps_2</strong> (np.ndarray, optional):\nOptional second set of input maps for cross-covariance computation.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Covariance matrix, either global (2D) or pixel-dependent (3D).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">input_maps</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">fwhm_out</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">b_ell</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">mask</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">input_maps_2</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs.get_mcilc_cov", "modulename": "broom.ilcs", "qualname": "get_mcilc_cov", "kind": "function", "doc": "<p>Compute pixel-wise covariance matrices for MC-ILC based on patching and optional donut-masking.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>inputs</strong> (np.ndarray):\nInput sky maps, shape (n_channels, n_pixels).</li>\n<li><strong>patches</strong> (np.ndarray):\nPixel-wise patch labels.</li>\n<li><strong>mask_mcilc</strong> (np.ndarray):\nBinary mask to include/exclude pixels.</li>\n<li><strong>reduce_bias</strong> (bool, default=True):\nWhether to apply donut masking to reduce MCILC bias.</li>\n<li><strong>mcilc_rings</strong> (int, default=4):\nNumber of HEALPix neighbor rings to exclude when reducing bias.</li>\n<li><strong>inputs_2</strong> (np.ndarray, optional):\nOptional second set of input maps for cross-covariance computation.</li>\n<li><strong>variance</strong> (bool, optional):\nIf True, compute variance instead of power between maps. Default is False.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Covariance matrix per pixel, shape (n_channels, n_channels, n_valid_pixels).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">inputs</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">patches</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">mask_mcilc</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">reduce_bias</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">mcilc_rings</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">4</span>,</span><span class=\"param\">\t<span class=\"n\">inputs_2</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">variance</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.ilcs.get_inv_cov", "modulename": "broom.ilcs", "qualname": "get_inv_cov", "kind": "function", "doc": "<p>Invert covariance matrices for ILC or MC-ILC processing.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>cov</strong> (np.ndarray):\nCovariance matrix of shape (n_channels, n_channels) or (n_channels, n_channels, n_pixels).</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Inverted covariance matrix with same shape.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">cov</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.inputs", "modulename": "broom.inputs", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.leakage", "modulename": "broom.leakage", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.leakage.purify_master", "modulename": "broom.leakage", "qualname": "purify_master", "kind": "function", "doc": "<p>Purify the E and B modes of the input QU maps using purification in NaMaster package.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>QU_maps</strong> (array of Healpix maps):\nThe input maps containing Q and U components.</li>\n<li><strong>mask</strong> (array):\nThe mask to apply to the maps.</li>\n<li><strong>lmax</strong> (int):\nThe maximum multipole to consider for purification.</li>\n<li><strong>return_E</strong> (bool, optional):\nIf True, return the E-mode alms. Default is True.</li>\n<li><strong>return_B</strong> (bool, optional):\nIf True, return the B-mode alms. Default is True.</li>\n<li><strong>purify_E</strong> (bool, optional):\nIf True, perform purification of E modes. Default is False.</li>\n<li><strong>purify_B</strong> (bool, optional):\nIf True, perform purification of B modes. Default is True.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>alms_p</strong> (array):\nThe purified alms for E and/or B modes based on the input flags.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">QU_maps</span>,</span><span class=\"param\">\t<span class=\"n\">mask</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span>,</span><span class=\"param\">\t<span class=\"n\">return_E</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">return_B</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">purify_E</span><span class=\"o\">=</span><span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">purify_B</span><span class=\"o\">=</span><span class=\"kc\">True</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.leakage.purify_recycling", "modulename": "broom.leakage", "qualname": "purify_recycling", "kind": "function", "doc": "<p>Purify the E and B modes of the input QU maps using recycling technique.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>QU_maps</strong> (array of Healpix maps):\nThe input maps containing Q and U components.</li>\n<li><strong>QU_full_maps</strong> (array of Healpix maps):\nThe Q and U maps containing the full signal over which the purification is actually performed.</li>\n<li><strong>mask</strong> (array):\nThe mask to apply to the maps.</li>\n<li><strong>lmax</strong> (int):\nThe maximum multipole to consider for purification.</li>\n<li><strong>return_E</strong> (bool, optional):\nIf True, return the E-mode alms. Default is True.</li>\n<li><strong>return_B</strong> (bool, optional):\nIf True, return the B-mode alms. Default is True.</li>\n<li><strong>purify_B</strong> (bool, optional):\nIf True, perform purification of B modes. Default is True.</li>\n<li><strong>purify_E</strong> (bool, optional):\nIf True, perform purification of E modes. Default is False.</li>\n<li><strong>inpaint</strong> (bool, optional):\nIf True, perform inpainting correction after applying the recycling technique. Default is False.</li>\n<li><strong>iterations</strong> (int, optional):\nNumber of iterations for recycling purification. Default is 0.</li>\n<li><strong>iterations_inp</strong> (int, optional):\nNumber of iterations for inpainting correction. Default is 1000.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>alms_p</strong> (array):\nThe purified alms for E and/or B modes based on the input flags.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">QU_maps</span>,</span><span class=\"param\">\t<span class=\"n\">QU_full_maps</span>,</span><span class=\"param\">\t<span class=\"n\">mask</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span>,</span><span class=\"param\">\t<span class=\"n\">return_E</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">return_B</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">purify_B</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">purify_E</span><span class=\"o\">=</span><span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">inpaint</span><span class=\"o\">=</span><span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">iterations</span><span class=\"o\">=</span><span class=\"mi\">0</span>,</span><span class=\"param\">\t<span class=\"n\">iterations_inp</span><span class=\"o\">=</span><span class=\"mi\">1000</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.leakage.purify_inpainting", "modulename": "broom.leakage", "qualname": "purify_inpainting", "kind": "function", "doc": "<p>Purify the E and B modes of the input QU maps using inpainting technique. \nAfter applying inpainting, the maps can be further purified with iterative harmonic transformations.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>QU_maps</strong> (array of Healpix maps):\nThe input maps containing Q and U components.</li>\n<li><strong>mask</strong> (array):\nThe mask to apply to the maps.</li>\n<li><strong>lmax</strong> (int):\nThe maximum multipole to consider for purification.</li>\n<li><strong>return_E</strong> (bool, optional):\nIf True, return the E-mode alms. Default is True.</li>\n<li><strong>return_B</strong> (bool, optional):\nIf True, return the B-mode alms. Default is True.</li>\n<li><strong>purify_B</strong> (bool, optional):\nIf True, perform purification of B modes. Default is True.</li>\n<li><strong>purify_E</strong> (bool, optional):\nIf True, perform purification of E modes. Default is False.</li>\n<li><strong>iterations</strong> (int, optional):\nNumber of iterations for recycling purification. Default is 0.</li>\n<li><strong>iterations_inp</strong> (int, optional):\nNumber of iterations for inpainting correction. Default is 1000.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>alms_p</strong> (array):\nThe purified alms for E and/or B modes based on the input flags.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">QU_maps</span>,</span><span class=\"param\">\t<span class=\"n\">mask</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span>,</span><span class=\"param\">\t<span class=\"n\">return_E</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">return_B</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">purify_B</span><span class=\"o\">=</span><span class=\"kc\">True</span>,</span><span class=\"param\">\t<span class=\"n\">purify_E</span><span class=\"o\">=</span><span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">iterations</span><span class=\"o\">=</span><span class=\"mi\">0</span>,</span><span class=\"param\">\t<span class=\"n\">iterations_inp</span><span class=\"o\">=</span><span class=\"mi\">1000</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.masking", "modulename": "broom.masking", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.masking.is_binary_mask", "modulename": "broom.masking", "qualname": "is_binary_mask", "kind": "function", "doc": "<p>Check if a mask is binary (contains only 0.0 and 1.0).</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>mask</strong> (np.ndarray):\nThe input mask.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>bool</strong>: True if binary, False otherwise.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">mask</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.masking.get_threshold_mask", "modulename": "broom.masking", "qualname": "get_threshold_mask", "kind": "function", "doc": "<p>Apply a threshold-based masking strategy to reduce the sky fraction.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>map_</strong> (np.ndarray):\nInput residual tracer map(s), shape (n_fields, npix) or (npix,) to be thresholded.</li>\n<li><strong>mask_init</strong> (np.ndarray):\nInitial binary mask.</li>\n<li><strong>field_cls_in</strong> (str):\nFields associated to map_ (e.g., \"TQU\", \"QU\").</li>\n<li><strong>fsky</strong> (float):\nDesired final sky fraction.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole to consider.</li>\n<li><strong>smooth_tracer</strong> (float):\nFWHM in degrees for smoothing the tracer map.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Final binary mask with the desired sky fraction.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">map_</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">mask_init</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">field_cls_in</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">fsky</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">smooth_tracer</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">3.0</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.masking.threshold_scalar_tracer", "modulename": "broom.masking", "qualname": "threshold_scalar_tracer", "kind": "function", "doc": "<p>Generate a threshold mask from a scalar tracer map.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>map_</strong> (np.ndarray):\nScalar tracer map.</li>\n<li><strong>mask_in</strong> (np.ndarray):\nInitial mask.</li>\n<li><strong>npix_mask</strong> (int):\nNumber of additional pixels to mask.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole to be considerd for smoothing the tracer map.</li>\n<li><strong>smooth_tracer</strong> (float):\nSmoothing FWHM in degrees.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Threshold mask.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">map_</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">mask_in</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">npix_mask</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">smooth_tracer</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">3.0</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.masking.threshold_P_tracer", "modulename": "broom.masking", "qualname": "threshold_P_tracer", "kind": "function", "doc": "<p>Generate a threshold mask from polarization tracers maps (Q, U).</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>map_</strong> (np.ndarray):\nPolarization tracers maps [Q, U]. Shape: (2, npix).</li>\n<li><strong>mask_in</strong> (np.ndarray):\nInitial mask.</li>\n<li><strong>npix_mask</strong> (int):\nNumber of pixels to mask.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole to be considerd for smoothing the tracers maps.</li>\n<li><strong>smooth_tracer</strong> (float):\nSmoothing FWHM in degrees.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong> ():\nThresholded polarization mask.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">map_</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">mask_in</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">npix_mask</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">smooth_tracer</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">3.0</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.masking.get_planck_mask", "modulename": "broom.masking", "qualname": "get_planck_mask", "kind": "function", "doc": "<p>Downloads and processes a Planck Galactic mask.</p>\n\n<h2 id=\"parameters\">Parameters</h2>\n\n<pre><code>apo: int \n    Apodization level (default 5).\nnside: int \n    HEALPix resolution.\nfield: int \n    Field to read.\ninfo: bool \n    Whether to return header info.\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray or tuple</strong> ():\nMask data or (mask, header).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">apo</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">5</span>,</span><span class=\"param\">\t<span class=\"n\">nside</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">2048</span>,</span><span class=\"param\">\t<span class=\"n\">field</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">3</span>,</span><span class=\"param\">\t<span class=\"n\">info</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"nb\">tuple</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.masking.get_masks_for_compsep", "modulename": "broom.masking", "qualname": "get_masks_for_compsep", "kind": "function", "doc": "<p>Get observation and covariance masks for component separation.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>mask_obs</strong> (Union[str, np.ndarray, None]):\nPath to the observation mask fits file or a numpy array. If None, no observation mask is applied.</li>\n<li><strong>mask_cov</strong> (Union[str, np.ndarray, None]):\nPath to the covariance mask fits file or a numpy array. If None, the observation mask is used as the covariance mask.</li>\n<li><strong>nside</strong> (int):\nHEALPix resolution for the masks in output.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Tuple[Union[np.ndarray, None], Union[np.ndarray, None]]:</strong>: Tuple containing the observation mask and covariance mask as numpy arrays. If no mask is provided, returns None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">mask_obs</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">mask_cov</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nside</span><span class=\"p\">:</span> <span class=\"nb\">int</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.needlets", "modulename": "broom.needlets", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.needlets.get_cosine_windows", "modulename": "broom.needlets", "qualname": "get_cosine_windows", "kind": "function", "doc": "<p>Generate cosine-based needlet windows.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>lmax</strong> (int):\nMaximum multipole.</li>\n<li><strong>needlet_config</strong> (dict):\nConfiguration with key \"ell_peaks\" (list of peak positions).</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Cosine window array (n_bands, lmax+1).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">needlet_config</span><span class=\"p\">:</span> <span class=\"n\">Dict</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.needlets.get_standard_windows", "modulename": "broom.needlets", "qualname": "get_standard_windows", "kind": "function", "doc": "<p>Generate standard needlet windows.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>lmax</strong> (int):\nMaximum multipole.</li>\n<li><strong>needlet_config</strong> (dict):\nMust contain 'width' and optionally 'merging_needlets'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Standard needlet windows.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">needlet_config</span><span class=\"p\">:</span> <span class=\"n\">Dict</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.needlets.get_mexican_windows", "modulename": "broom.needlets", "qualname": "get_mexican_windows", "kind": "function", "doc": "<p>Generate Mexican needlet windows.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>lmax</strong> (int):\nMaximum multipole.</li>\n<li><strong>needlet_config</strong> (dict):\nMust contain 'width' and optionally 'merging_needlets'.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Mexican needlet windows.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">needlet_config</span><span class=\"p\">:</span> <span class=\"n\">Dict</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.pilcs", "modulename": "broom.pilcs", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.pilcs.pilc", "modulename": "broom.pilcs", "qualname": "pilc", "kind": "function", "doc": "<p>Perform Polarization Internal Linear Combination (PILC) on input alm coefficients.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing global settings. It includes:\n<ul>\n<li>lmax : int, maximum multipole for the component separation.</li>\n<li>nside : int, HEALPix resolution parameter for compsep products.</li>\n<li>fwhm_out : float, full width at half maximum of the output beam in arcminutes.</li>\n<li>pixel_window_out : bool, whether to apply a pixel window to the output maps.</li>\n<li>field_out : str, desired output fields (e.g., \"E\", \"B\", \"QU\", \"QU_E\", \"QU_B\").</li>\n<li>save_compsep_products : bool, whether to save component separation products.</li>\n<li>return_compsep_products : bool, whether to return component separation products.</li>\n<li>path_outputs : str, path to save the output files.</li>\n<li>units : str, units of the output maps (e.g., \"uK_CMB\"). Used to compute components SEDs, if needed.</li>\n<li>bandpass_integrate : bool, whether inputs are bandpass-integrated. Used to compute components SEDs, if needed.</li>\n</ul></li>\n<li><strong>input_alms</strong> (SimpleNamespace):\nSimpleNamespace object containing input spherical harmonic coefficients (alms). \nEach attribute has shape (n_channels, (n_fields), n_alms), where n_fields depend on the fields requested in config.field_out. \nn_fields can be None if only E and B are requested, or 2 if both are requested to be included in P component separation.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary specifying component separation parameters. It includes:\n<ul>\n<li>\"method\": Method to use for component separation (e.g., \"pilc\", \"cpilc\", \"prilc\", \"cprilc\", ..)</li>\n<li>\"domain\": Domain of the component separation (e.g., \"pixel\", \"needlet\").</li>\n<li>\"needlet_config\": Configuration for needlet parameters (if applicable).</li>\n<li>\"ilc_bias\": Parameter setting the residual percentage ILC bias (default is 0. and covariance will be computed over the whole sky).</li>\n<li>\"reduce_ilc_bias\": Boolean. If True, it implements a procedure to attenuate ILC bias.</li>\n<li>\"save_needlets\": boolean. Whether to save adopted needlet bands in the output directory. \nIf not provided, it is set to the value of config.save_compsep_products. Default: True.</li>\n<li>\"save_weights\": boolean. Whether to save compsep weights maps in the output directory.\nIf not provided, it is set to the value of config.save_compsep_products. Default: True.</li>\n<li>\"mask\": (optional) HEALPix mask which will exclude (unobserved) regions from covariance computation. \nIt must be a 1D array with shape (12 * nside**2,). If non-binary, it will be used to weigh pixel in covariance computation.</li>\n<li>\"cov_noise_debias\": (float, list) Noise covariance debiasing factor. \nIf different from 0. it will debias the covariance matrix by a factor cov_noise_debias * noise_covariance.\nIt must be a list with the same length as the number of needlet scales if domain is \"needlet\", otherwise a single float.</li>\n<li>\"special_nls\": (list) List of needlet scales where component deprojection is applied in c_pilc.</li>\n<li>\"constraints\": Dictionary to be used if method is \"cpilc\", \"cprilc\", \"c_pilc\" or \"c_prilc\". It must contain:\n<ul>\n<li>\"components\": list of strings with components to be deprojected in cPILC. It can be a list of lists if domain is \"needlet\".\nEach list will be associated to a needlet band in order.\nOptionally can include:</li>\n<li>\"beta_d\": (float, list): dust spectral index to compute dust moments. If list, a different beta_d is used for each needlet band. Default: 1.54.</li>\n<li>\"T_d\": (float, list): dust temperature to compute dust moments. If list, a different T_d is used for each needlet band. Default: 19.6.</li>\n<li>\"beta_s\": (float, list): synchrotron spectral index to compute synchrotron moments. If list, a different beta_s is used for each needlet band. Default: -3.</li>\n<li>\"deprojection\": (float, list): deprojection factor for each component. If list, a different deprojection factor is used for each component.\nIt can be a list of lists if domain is \"needlet\". Each list will be associated to a needlet band in order. Default: 0. (i.e. full deprojection) for each component and each needlet band.</li>\n</ul></li>\n</ul></li>\n<li>**<strong>kwargs</strong> (dict):\nAdditional keyword arguments forwarded to hp.map2alm.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace or None</strong>: Output maps if config.return_compsep_products is True, otherwise None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.pilcs.get_prilc_weights", "modulename": "broom.pilcs", "qualname": "get_prilc_weights", "kind": "function", "doc": "<p>Compute real weights for the Polarization Internal Linear Combination (PRILC) method,\nwith or without constraints to deproject additional components.</p>\n\n<h2 id=\"parameters\">Parameters:</h2>\n\n<pre><code>A_out: np.ndarray\n    Spectral energy distribution (SED) of the component to be reconstructed (e.g., CMB). Shape (n_channels,).\ninv_cov: np.ndarray\n    Inverse covariance matrix of input polarization maps:\n    - If ilc_bias=0: shape (n_channels, n_channels)\n    - If ilc_bias!=0: shape (n_channels, n_channels, n_pixels)\ninput_shapes: Tuple[int, ...]\n    Shape of the input map (n_channels, 2, n_pixels, n_comps) or equivalent, used to determine spatial size and channels.\ncompsep_run: Dict\n    Dictionary with component separation settings. See 'pilc' function for details.\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>w_ilc</strong> (np.ndarray):\nILC weights, shaped:\n    - (n_channels,) if ilc_bias = 0\n    - (n_channels, n_pixels) if ilc_bias != 0</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">A_out</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">inv_cov</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">input_shapes</span><span class=\"p\">:</span> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.pilcs.get_pilc_weights", "modulename": "broom.pilcs", "qualname": "get_pilc_weights", "kind": "function", "doc": "<p>Compute weights for the Polarization Internal Linear Combination (PILC) method,\nwith or without constraints to deproject additional components.</p>\n\n<h2 id=\"parameters\">Parameters:</h2>\n\n<pre><code>A_out: np.ndarray\n    Spectral energy distribution (SED) of the component to be reconstructed (e.g., CMB). Shape (n_channels,).\ninv_cov: np.ndarray\n    Inverse covariance matrix of input polarization maps:\n    - If ilc_bias=0: shape (n_channels, n_channels)\n    - If ilc_bias!=0: shape (n_channels, n_channels, n_pixels)\ninput_shapes: Tuple[int, ...]\n    Shape of the input map (n_channels, 2, n_pixels, n_comps) or equivalent, used to determine spatial size and channels.\ncompsep_run: Dict\n    Dictionary with component separation settings. See 'pilc' function for details.\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>w_ilc</strong> (np.ndarray):\nILC weights, shaped:\n    - (n_channels,) if ilc_bias = 0\n    - (n_channels, n_pixels) if ilc_bias != 0</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">A_out</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">inv_cov</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">input_shapes</span><span class=\"p\">:</span> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.pilcs.get_pilc_cov", "modulename": "broom.pilcs", "qualname": "get_pilc_cov", "kind": "function", "doc": "<p>Compute full PILC covariance matrix.</p>\n\n<h2 id=\"parameters\">Parameters:</h2>\n\n<pre><code>input_maps: np.ndarray\n    input Q/U maps. Shape (n_channels, 2, n_pixels)\nlmax: int\n    Maximum multipole for the analysis.\ncompsep_run: Dict\n    Dictionary with component separation settings. See 'pilc' function for details.\nfwhm_out: float\n    Output beam FWHM in arcminutes.\nb_ell: np.ndarray\n    Needlet window function for the current scale. It should be a 1D array of shape (lmax+1,).\ninput_maps_2: np.ndarray, optional\n    Optional second set of input Q/U maps for cross-covariance computation. Shape (n_channels, 2, n_pixels).\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>cov</strong> (np.ndarray):\nFull 2x2 polarization covariance matrix of shape (2<em>n_channels, 2</em>n_channels, [n_pixels]).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">input_maps</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">fwhm_out</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">b_ell</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">input_maps_2</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.pilcs.get_prilc_cov", "modulename": "broom.pilcs", "qualname": "get_prilc_cov", "kind": "function", "doc": "<p>Compute the reduced ILC covariance matrix for polarization maps.</p>\n\n<h2 id=\"parameters\">Parameters:</h2>\n\n<pre><code>input_maps: np.ndarray\n    input Q/U maps. Shape (n_channels, 2, n_pixels)\nlmax: int\n    Maximum multipole for the analysis.\ncompsep_run: Dict\n    Dictionary with component separation settings. See 'pilc' function for details.\nfwhm_out: float\n    Output beam FWHM in arcminutes.\nb_ell: np.ndarray\n    Needlet window function for the current scale. It should be a 1D array of shape (lmax+1,).\ninput_maps_2: np.ndarray, optional\n    Optional second set of input Q/U maps for cross-covariance computation. Shape (n_channels, 2, n_pixels).\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>cov</strong> (np.ndarray):\nCovariance matrix of shape (n_channels, n_channels, [n_pixels]).</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">input_maps</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">fwhm_out</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">b_ell</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">input_maps_2</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines", "modulename": "broom.routines", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.routines.taper_beam_to_zero", "modulename": "broom.routines", "qualname": "taper_beam_to_zero", "kind": "function", "doc": "<p>Taper function to zero between ell0 and ell1 for beams.</p>\n\n<ul>\n<li>for ell &lt;= ell0: unchanged (W=1)</li>\n<li>for ell0 &lt; ell &lt;= ell1: smoothly tapered</li>\n<li>for ell &gt; ell1: zero</li>\n</ul>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>l</strong> (ndarray):\narray of multipole moments</li>\n<li><strong>ell0</strong> (int):\nmultipole below which the beam is unchanged</li>\n<li><strong>ell1</strong> (int):\nmultipole above which the beam is set to zero</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>taper_window</strong> (ndarray):\nmultiplicative window to be applied to bl (1 for ell&lt;=ell0, 0 for ell>ell1)</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">l</span>, </span><span class=\"param\"><span class=\"n\">ell0</span>, </span><span class=\"param\"><span class=\"n\">ell1</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.get_fwhm_for_cov", "modulename": "broom.routines", "qualname": "get_fwhm_for_cov", "kind": "function", "doc": "<p>Compute the FWHM required for smoothing the covariance matrix.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>lmax</strong> (int):\nMaximum multipole.</li>\n<li><strong>n_pixels</strong> (int):\nNumber of pixels in the map.</li>\n<li><strong>n_channels</strong> (int):\nNumber of frequency channels.</li>\n<li><strong>ilc_bias</strong> (float):\nILC bias parameter.</li>\n<li><strong>b_ell</strong> (np.ndarray, optional):\nNeedlet transfer function. Defaults to unity.</li>\n</ul>\n\n<p>Returns\n    float\n        FWHM in radians.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">lmax</span>, </span><span class=\"param\"><span class=\"n\">n_pixels</span>, </span><span class=\"param\"><span class=\"n\">n_channels</span>, </span><span class=\"param\"><span class=\"n\">ilc_bias</span>, </span><span class=\"param\"><span class=\"n\">fwhm_out</span>, </span><span class=\"param\"><span class=\"n\">b_ell</span><span class=\"o\">=</span><span class=\"kc\">None</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.merge_dicts", "modulename": "broom.routines", "qualname": "merge_dicts", "kind": "function", "doc": "<p>Merge a list of single-key dictionaries into one dictionary, or return the dictionary itself.</p>\n\n<h2 id=\"parameters\">Parameters:</h2>\n\n<pre><code>d: dictionary or a list of dictionaries\n    If a list, each dict is expected to have exactly one key.\n</code></pre>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>Dict[Any, Any]</strong>: A single merged dictionary.</li>\n</ul>\n\n<h6 id=\"raises\">Raises</h6>\n\n<ul>\n<li><strong>ValueError</strong> ():\nIf input is not a dict or list of single-key dicts.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">d</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"n\">Any</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]],</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"n\">Any</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]]</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"n\">Any</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.obj_to_array", "modulename": "broom.routines", "qualname": "obj_to_array", "kind": "function", "doc": "<p>Convert a SimpleNamespace object with specified attributes into a numpy array.</p>\n\n<p>Attributes are stacked along the last axis.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>obj</strong>: SimpleNamespace with attributes like \"total\", \"fgds\", etc.</li>\n<li><strong>return_attributes</strong> (bool):\nIf True, return the list of attributes of the object instead of the numpy array.\nDefault is False.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: A numpy array stacking the specified attributes if <code>return_attributes</code> is False.</li>\n<li><strong>List[str]</strong>: List of attribute names if <code>return_attributes</code> is True.</li>\n</ul>\n\n<h6 id=\"raises\">Raises</h6>\n\n<ul>\n<li><strong>ValueError</strong> (If input is not a SimpleNamespace.):</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">obj</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">return_attributes</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.obj_out_to_array", "modulename": "broom.routines", "qualname": "obj_out_to_array", "kind": "function", "doc": "<p>Convert a SimpleNamespace object with output-related attributes to a numpy array.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>obj</strong>: SimpleNamespace with attributes like \"output_total\", \"noise_residuals\", etc.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: A numpy array stacking the specified attributes.</li>\n</ul>\n\n<h6 id=\"raises\">Raises</h6>\n\n<ul>\n<li><strong>ValueError</strong> (If input is not a SimpleNamespace.):</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">obj</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.array_to_obj", "modulename": "broom.routines", "qualname": "array_to_obj", "kind": "function", "doc": "<p>Convert a numpy array back to a SimpleNamespace object with specific attributes,\nbased on attributes present in the reference object.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>array</strong> (np.ndarray):\nNumpy array where the last dimension corresponds to attributes.</li>\n<li><strong>attr_list</strong> (List[str]):\nList of attributes to assign from the array slices.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace</strong>: SimpleNamespace with attributes set from array slices.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">array</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">attr_list</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.change_coord_mask", "modulename": "broom.routines", "qualname": "change_coord_mask", "kind": "function", "doc": "<p>Change coordinates of a HEALPIX mask</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>mask</strong> (np.ndarray):\nmask(s) to be rotated. It can be a single mask or a stack of masks.\nShape is (n_maps, n_pixels) or (n_pixels,).</li>\n<li><strong>coord</strong> (list):\nList of strings.\nFirst character is the coordinate system of mask, second character\nis the coordinate system of the output mask. As in HEALPIX, allowed\ncoordinate systems are 'G' (galactic), 'E' (ecliptic) or 'C' (equatorial)</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Mask(s) in the new coordinate system.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">mask</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">coord</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.nside_from_fwhm", "modulename": "broom.routines", "qualname": "nside_from_fwhm", "kind": "function", "doc": "<p>Compute the minimum HEALPix nside (power of 2) such that\nthe pixel size is &lt;= FWHM / pixs_per_fwhm.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>fwhm</strong> (float):\nBeam FWHM.</li>\n<li><strong>unit</strong> ({\"arcmin\", \"deg\", \"rad\"}, optional):\nUnit of <code>fwhm</code>. Default is arcmin.</li>\n<li><strong>pixs_per_fwhm</strong> (float, optional):\nNumber of pixels per FWHM. Default is 3.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>nside</strong> (int):\nSmallest power-of-two nside such that the typical\nHEALPix pixel size is &lt;= FWHM/pixs_per_fwhm.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">fwhm</span>, </span><span class=\"param\"><span class=\"n\">pixs_per_fwhm</span><span class=\"o\">=</span><span class=\"mf\">3.0</span>, </span><span class=\"param\"><span class=\"n\">unit</span><span class=\"o\">=</span><span class=\"s1\">&#39;arcmin&#39;</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.get_prefix", "modulename": "broom.routines", "qualname": "get_prefix", "kind": "function", "doc": "<p>Get the prefix of a model from a list of prefixes.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>model</strong> (str):\nModel name.</li>\n<li><strong>prefixes</strong> (List[str]):\nList of possible prefixes.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>str or None</strong>: The matching prefix if found, otherwise None.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">model</span>, </span><span class=\"param\"><span class=\"n\">prefixes</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.routines.get_fields_from_alms", "modulename": "broom.routines", "qualname": "get_fields_from_alms", "kind": "function", "doc": "<p>Determine the fields present in the input alms based on their shape and the configuration parameters.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>input_alms</strong> (np.ndarray):\nInput alms array, which can have different shapes depending on the fields included.</li>\n<li><strong>field_out</strong> (str):\nDesired output field type (e.g., \"T\", \"E\", \"B\", \"EB\", \"QU_E\", \"QU_B\").</li>\n</ul>\n\n<p>Returns\n    List[str]\n        List of field identifiers (e.g., \"T\", \"E\", \"B\") corresponding to the input alms.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">input_alms</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">field_out</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving", "modulename": "broom.saving", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.saving.get_gilc_maps", "modulename": "broom.saving", "qualname": "get_gilc_maps", "kind": "function", "doc": "<p>Load GILC component separation results (total signal, noise residuals, and foreground residuals) of all frequency channels\nprovided in the instrument object and for a given simulation run and field. </p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing instrument and output specifications.</li>\n<li><strong>gilc_config</strong> (Dict[str, Any]):\nDictionary containing GNILC configuration parameters, including:\n    path_gilc : str\n        Root path to the GNILC output directory. The full path will be given by '{config.path_outputs}/{path_gilc}'.\n    gilc_components : List[str]\n        List of GNILC components to load. Possible elements are \"output_total\", \"noise_residuals\", \"fgds_residuals\".\n    field_in : Optional[str], default=None\n        Type of field to load (\"T\", \"QU\", \"EB\", \"TQU\", \"TEB\", etc.). If None, default is config.field_out.</li>\n<li><strong>nsim</strong> (Optional[Union[str, int]], default=None):\nSimulation identifier, if any (used to select specific simulation output files).</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>gnilc_maps</strong> (SimpleNamespace):\nA container of numpy arrays with attributes corresponding to the requested GNILC components:</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">gilc_config</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.save_ilc_weights", "modulename": "broom.saving", "qualname": "save_ilc_weights", "kind": "function", "doc": "<p>Save ILC component separation weights to disk with appropriate metadata in filename.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object.</li>\n<li><strong>w</strong> (np.ndarray):\ncomponent separation weights to be saved.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary with component separation parameters.</li>\n<li><strong>nside_</strong> (int):\nHEALPix NSIDE resolution of the output.</li>\n<li><strong>nl_scale</strong> (int, optional):\nNeedlet scale index for the corresponding ILC run.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: It saves the weights to disk in the specified directory structure \nbased on the component separation method and configuration.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">w</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">nside_</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">nl_scale</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.update_and_save_nuiscov_serial", "modulename": "broom.saving", "qualname": "update_and_save_nuiscov_serial", "kind": "function", "doc": "<p>Load, update, and save nuisance covariance matrices to disk with appropriate metadata in filename.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object.</li>\n<li><strong>cov_n</strong> (np.ndarray):\nNuisance covariance matrix to be added to the average covariance.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary with parameters for nuisance covariance computation.</li>\n<li><strong>nside_</strong> (int):\nHEALPix NSIDE resolution of the nuisance covariance.</li>\n<li><strong>nl_scale</strong> (int, optional):\nNeedlet scale index associated with the nuisance covariance.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: It loads, updates, and saves the nuisance covariance matrices to disk in the specified directory structure</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">cov_n</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">nside_</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">nl_scale</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.load_nuiscov", "modulename": "broom.saving", "qualname": "load_nuiscov", "kind": "function", "doc": "<p>Load nuisance covariance matrices from disk.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object.</li>\n<li><strong>path_cov</strong> (str):\nPath to the nuisance covariance matrix to be loaded.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary with parameters for nuisance covariance computation.</li>\n<li><strong>nside_</strong> (int):\nHEALPix NSIDE resolution of the nuisance covariance.</li>\n<li><strong>nuisance</strong> (str or List[str]):\nNuisance component(s) to be included in the covariance. Can be a single string or a list of strings.</li>\n<li><strong>nl_scale</strong> (int, optional):\nNeedlet scale index associated with the nuisance covariance.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: It loads, updates, and saves the nuisance covariance matrices to disk in the specified directory structure</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">path_cov</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">nside_</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">nuisance</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]]</span>,</span><span class=\"param\">\t<span class=\"n\">nl_scale</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.save_patches", "modulename": "broom.saving", "qualname": "save_patches", "kind": "function", "doc": "<p>Save MC-ILC patches to disk with appropriate metadata in filename.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object.</li>\n<li><strong>patches</strong> (np.ndarray):\nMC-ILC patches to be saved.</li>\n<li><strong>compsep_run</strong> (dict):\nDictionary with component separation parameters.</li>\n<li><strong>nl_scale</strong> (int, optional):\nNeedlet scale index for the corresponding ILC run.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: It saves the MC-ILC patches to disk in the specified directory structure</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">patches</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">compsep_run</span><span class=\"p\">:</span> <span class=\"n\">Dict</span>,</span><span class=\"param\">\t<span class=\"n\">nl_scale</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.save_spectra", "modulename": "broom.saving", "qualname": "save_spectra", "kind": "function", "doc": "<p>Save the computed spectra to files based on the configuration and compute_cls dictionary.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing parameters for spectra computation. See <code>_compute_spectra</code> for details.</li>\n<li><strong>cls_out</strong> (SimpleNamespace):\nObject containing computed spectra with attributes for each component.</li>\n<li><strong>compute_cls</strong> (dict):\nDictionary containing parameters for spectra computation. See <code>_compute_spectra</code> for details.</li>\n<li><strong>nsim</strong> (str, optional):\nSimulation number to save spectra.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>None</strong>: It saves the computed spectra to disk in the specified directory structure.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">cls_out</span><span class=\"p\">:</span> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>,</span><span class=\"param\">\t<span class=\"n\">compute_cls</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.saving.get_path_spectra", "modulename": "broom.saving", "qualname": "get_path_spectra", "kind": "function", "doc": "<p>Get the path where spectra will be saved based on the compute_cls dictionary.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration object containing paths and parameters for spectra computation.</li>\n<li><strong>compute_cls</strong> (dict):\nDictionary containing parameters for spectra computation, including mask type and fsky.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>str</strong>: Full path to the directory where spectra will be saved.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>, </span><span class=\"param\"><span class=\"n\">compute_cls</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.seds", "modulename": "broom.seds", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.simulations", "modulename": "broom.simulations", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.simulations.get_input_data", "modulename": "broom.simulations", "qualname": "get_input_data", "kind": "function", "doc": "<p>Load or generate input data for component separation including total coadded signal, CMB, noise and foregrounds.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration parameters. It should have the following attributes:\n<ul>\n<li><code>generate_input_cmb</code>: Whether to generate CMB maps. If False, it will try to load them from <code>cmb_path</code>.</li>\n<li><code>cmb_path</code>: Path where saving or loading CMB maps.</li>\n<li>'cls_cmb_path': Path to the CMB power spectrum FITS file. Used if 'generate_input_cmb' is True.</li>\n<li>'seed_cmb': Seed for CMB generation (optional).</li>\n<li>'cls_cmb_new_ordered': Whether the new ordering of Cls is used in the CMB power spectrum FITS file.</li>\n<li><code>generate_input_noise</code>: Whether to generate noise maps. If False, it will try load them from <code>noise_path</code>.</li>\n<li><code>noise_path</code>: Path where saving or loading noise maps.</li>\n<li><code>seed_noise</code>: Seed for noise generation (optional).</li>\n<li><code>data_splits</code>: Whether to generate/load noise and data splits.</li>\n<li><code>only_splits</code>: Whether to generate/load only noise and data splits, without full coadded maps.</li>\n<li><code>generate_input_data</code>: Whether to generate total data maps. If False, it will try to load them from <code>data_path</code>.</li>\n<li><code>data_path</code>: Path where saving or loading total data maps.</li>\n<li><code>save_inputs</code>: Whether to save generated inputs to disk.</li>\n<li><code>lmax_in</code>: Desired maximum multipole for the simulation.</li>\n<li><code>nside_in</code>: Desired HEALPix resolution. It will be used also to convolve the input maps for the pixel window function, if requested.</li>\n<li><code>units</code>: Units for the maps (e.g., 'uK_CMB').</li>\n<li><code>lmin_in</code>: Desired minimum multipole to keep in the simulation. Default is 2.</li>\n<li><code>pixel_window_in</code>: Whether to apply pixel window smoothing to the input maps.</li>\n<li>'generate_input_foregrounds': Whether to generate foreground maps. If False, it will try to load them from <code>fgds_path</code>.</li>\n<li><code>return_fgd_components</code>: Whether to return individual foreground components.</li>\n<li><code>fgds_path</code>: Path where saving or loading foreground maps.</li>\n<li><code>data_type</code>: Type of data to return, either \"maps\" or \"alms\".</li>\n<li><code>bandpass_integrate</code>: Whether to integrate sky components across bandpasses.</li>\n<li><code>coordinates</code>: Coordinate system for the maps (e.g., \"G\" for Galactic).</li>\n<li>'instrument': a dictionary containing the instrument configuration, including:\n<ul>\n<li><code>frequency</code>: List of instrument frequencies in GHz.</li>\n<li><code>beams</code>: Type of beams to be used (e.g., \"gaussian\", \"file_l\", \"file_lm\").</li>\n<li><code>fwhm</code>: List of full width at half maximum (FWHM) for each frequency channel in arcmin. Used if beams are \"gaussian\".</li>\n<li>'depth_I': Depth for intensity maps in arcmin<em>uK_CMB (optional). \nIf not provided, it will be assumed to be the polarization depth divided by sqrt(2).\nUsed if path_depth_maps is not provided.</li>\n<li>'depth_P': Depth for polarization maps in arcmin</em>uK_CMB (optional).\nIf not provided, it will be assumed to be the intensity depth multiplied by sqrt(2).\nUsed if path_depth_maps is not provided.</li>\n<li><code>path_beams</code>: Path to the beam files (if using \"file_l\" or \"file_lm\" beams).\nThe code will look for files named \"{path_beams}_{channel_tag}.fits\" for each frequency channel.</li>\n<li><code>channels_tags</code>: List of tags for each frequency channel, used for loading beams, bandpasses or depth maps.</li>\n<li>'bandwidths': List of relative bandwidths for each frequency channel (optional, used if bandpass_integrate is True).\nUsed if path_bandpasses is not provided.</li>\n<li><code>path_depth_maps</code>: Full path to standard deviation maps (optional, used if generating noise).\nThe code will look for files named \"{path_depth_maps}_{channel_tag}.fits\" for each frequency channel.<br />\nThey are assumed to be in uK_CMB units.</li>\n<li><code>path_hits_maps</code>: Full path to hits maps (optional, used if generating noise and 'path_depth_maps' is not provided).\nIf it does not end with .fits, the code will look for files named \n\"{path_hits_maps}_{channel_tag}.fits\" for each frequency channel.</li>\n<li><code>path_bandpasses</code>: Path to bandpass files (optional, used if bandpass_integrate is True).\nThe code will look for files named as \"{path_bandpasses}_{channel_tag}.npy\" for each channel tag.\nEach file should be a 2D array which has the first column a list of frequencies in GHz and the second column the corresponding bandpass response.</li>\n<li><code>ell_knee</code>: Lists of knee frequencies for each channel for the noise power spectrum (optional).\nIf it is a single list it will be applied to temperature only.\nIf it is a list of two lists it will be applied to temperature (first list) and polarization (second list).\nIf not provided, white noise is assumed.</li>\n<li><code>alpha_knee</code>: List of spectral indices of the noise power spectrum for each channel (optional).\nIf not provided, white noise is assumed.</li>\n</ul></li>\n</ul></li>\n<li><strong>foregrounds</strong> (Optional[SimpleNamespace]):\nForeground components. If provided, they will be used instead of generating or loading them.</li>\n<li><strong>nsim</strong> (Optional[Union[int, str]]):\nSimulation number.</li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments forwarded to alm computation.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace</strong>: Data container potentially including co-added signal, CMB, noise, and foregrounds.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">foregrounds</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.simulations.get_noise_frequency_channel", "modulename": "broom.simulations", "qualname": "get_noise_frequency_channel", "kind": "function", "doc": "<p>Generate noise simulation for a single frequency channel.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration parameters including instrument settings. It should have the following attributes:\n<ul>\n<li><code>instrument.frequency</code>: List of instrument frequencies.</li>\n<li><code>instrument.path_depth_maps</code>: Path to depth maps (optional). </li>\n<li><code>instrument.path_hits_maps</code>: Path to hits maps (optional).</li>\n<li><code>nside_in</code>: Desired HEALPix resolution.</li>\n<li><code>lmax_in</code>: Maximum multipole for the simulation.</li>\n<li><code>data_type</code>: Type of data to return, either \"maps\" or \"alms\".</li>\n<li><code>units</code>: Units for the noise maps (e.g., 'uK_CMB').</li>\n<li><code>lmin_in</code>: Minimum multipole to keep in the simulation.</li>\n</ul></li>\n<li><strong>depth_i</strong> (List[float]):\nDepth for intensity maps for each frequency channel.</li>\n<li><strong>depth_p</strong> (List[float]):\nDepth for polarization maps for each frequency channel.</li>\n<li><strong>nf</strong> (int):\nIndex of the frequency channel to generate noise for.</li>\n<li><strong>depth_maps</strong> (Optional[np.ndarray]):\nDepth maps to use for noise generation (optional). Default is None.</li>\n<li><strong>hits_map</strong> (Optional[np.ndarray]):\nHits map to use for noise generation (optional). Default is None.</li>\n<li><strong>seed</strong> (Optional[int]):\nSeed for noise generation (optional). Default is None.</li>\n<li><strong>fell</strong> (Optional[np.ndarray]):\nEll filter to apply (optional). Default is None.</li>\n<li><strong>split</strong> (Optional[int]):\nData split index for noise generation (optional). Default is None.</li>\n<li><strong>kwargs</strong> (dict, optional):\nAdditional keyword arguments for <code>hp.map2alm</code>.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>np.ndarray</strong>: Noise maps or alms for the specified frequency channel. Shape is (3, n_pix) for maps or (3, n_alm) for alms.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">depth_i</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">float</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">depth_p</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">float</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">nf</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">depth_maps</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">hits_map</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">seed</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">fell</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">split</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.simulations.get_nuisance_data", "modulename": "broom.simulations", "qualname": "get_nuisance_data", "kind": "function", "doc": "<p>Get nuisance data for nuisance covariance estimation for a given simulation.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>config</strong> (Configs):\nConfiguration parameters including instrument settings and paths.</li>\n<li><strong>nuisance_comps</strong> (List[str]):\nList of nuisance components to include.</li>\n<li><strong>nuisance_path</strong> (str, optional):\nPath to precomputed nuisance inputs. If None, inputs will be generated/saved.</li>\n<li><strong>nsim</strong> (int or str, optional):\nSimulation index to load/save the maps (optional). Default: None.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>SimpleNamespace</strong> ():\nNuisance data containing CMB and noise simulations.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">broom</span><span class=\"o\">.</span><span class=\"n\">configurations</span><span class=\"o\">.</span><span class=\"n\">Configs</span>,</span><span class=\"param\">\t<span class=\"n\">nuisance_comps</span>,</span><span class=\"param\">\t<span class=\"n\">nuisance_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">nsim</span><span class=\"p\">:</span> <span class=\"n\">Union</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">NoneType</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">types</span><span class=\"o\">.</span><span class=\"n\">SimpleNamespace</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.spectra", "modulename": "broom.spectra", "kind": "module", "doc": "<p></p>\n"}, {"fullname": "broom.spectra.get_bls", "modulename": "broom.spectra", "qualname": "get_bls", "kind": "function", "doc": "<p>Get the beam transfer functions for the required fields and lmax.</p>\n\n<h6 id=\"parameters\">Parameters</h6>\n\n<ul>\n<li><strong>nside</strong> (int):\nHEALPix nside parameter.</li>\n<li><strong>fwhm</strong> (float):\nFull width at half maximum of the beam in arcminutes.</li>\n<li><strong>lmax</strong> (int):\nMaximum multipole to consider.</li>\n<li><strong>field_cls_out</strong> (list):\nList of fields for which to compute the angular power spectra. \nIt can contain any combination of the following: 'TT', 'EE', 'BB', 'TE', 'TB', 'EB'.</li>\n<li><strong>pixel_window_out</strong> (bool, optional):\nWhether to consider the pixel window function in the beam transfer functions. Default is True.</li>\n</ul>\n\n<h6 id=\"returns\">Returns</h6>\n\n<ul>\n<li><strong>bls_beam</strong> (np.ndarray):\nBeam transfer functions for the specified fields and lmax.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">nside</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">fwhm</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">lmax</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">field_cls_out</span><span class=\"p\">:</span> <span class=\"nb\">list</span>,</span><span class=\"param\">\t<span class=\"n\">pixel_window_out</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">True</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "broom.spectra.BBin", "modulename": "broom.spectra", "qualname": "BBin", "kind": "class", "doc": "<p>Class for binning power spectra into bands of ell values.</p>\n"}, {"fullname": "broom.spectra.BBin.__init__", "modulename": "broom.spectra", "qualname": "BBin.__init__", "kind": "function", "doc": "<p>ell_bins : list of arrays\n    Each element contains the ell values in that band.\nis_Dell : bool\n    If True, bin Dell instead of Cl.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">ell_bins</span>, </span><span class=\"param\"><span class=\"n\">lmax</span>, </span><span class=\"param\"><span class=\"n\">is_Dell</span><span class=\"o\">=</span><span class=\"kc\">False</span>, </span><span class=\"param\"><span class=\"n\">w_ell</span><span class=\"o\">=</span><span class=\"kc\">None</span></span>)</span>"}, {"fullname": "broom.spectra.BBin.ell_bins", "modulename": "broom.spectra", "qualname": "BBin.ell_bins", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.spectra.BBin.n_bands", "modulename": "broom.spectra", "qualname": "BBin.n_bands", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.spectra.BBin.lmax", "modulename": "broom.spectra", "qualname": "BBin.lmax", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.spectra.BBin.is_Dell", "modulename": "broom.spectra", "qualname": "BBin.is_Dell", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "broom.spectra.BBin.from_edges", "modulename": "broom.spectra", "qualname": "BBin.from_edges", "kind": "function", "doc": "<p>Create bins from lower/upper edges.</p>\n\n<p>ell_ini, ell_end : arrays of same length\n    Each pair defines one band: ell_ini[i] &lt;= ell &lt; ell_end[i]</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">bin_class</span>, </span><span class=\"param\"><span class=\"n\">ell_ini</span>, </span><span class=\"param\"><span class=\"n\">ell_end</span>, </span><span class=\"param\"><span class=\"n\">is_Dell</span><span class=\"o\">=</span><span class=\"kc\">False</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.spectra.BBin.from_lmax_linear", "modulename": "broom.spectra", "qualname": "BBin.from_lmax_linear", "kind": "function", "doc": "<p>Create linear bins of width nlb up to lmax.</p>\n\n<p>lmax : int\nnlb  : bin width (delta_ell)</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">bin_class</span>, </span><span class=\"param\"><span class=\"n\">lmax</span>, </span><span class=\"param\"><span class=\"n\">nlb</span>, </span><span class=\"param\"><span class=\"n\">is_Dell</span><span class=\"o\">=</span><span class=\"kc\">False</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.spectra.BBin.bin_cell", "modulename": "broom.spectra", "qualname": "BBin.bin_cell", "kind": "function", "doc": "<p>Bin power spectra.</p>\n\n<p>Accepts:</p>\n\n<ul>\n<li>cl shape (lmax+1,)</li>\n<li>cl shape (n_fields, lmax+1)</li>\n</ul>\n\n<p>Returns:</p>\n\n<ul>\n<li>if input was 1D: shape (n_bands,)</li>\n<li>if input was 2D: shape (n_fields, n_bands)</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">cl</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "broom.spectra.BBin.get_effective_ells", "modulename": "broom.spectra", "qualname": "BBin.get_effective_ells", "kind": "function", "doc": "<p>Get effective ell values for each band.</p>\n\n<p>Returns:</p>\n\n<ul>\n<li>effective_ells: array of shape (n_bands,)</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}];

    // mirrored in build-search-index.js (part 1)
    // Also split on html tags. this is a cheap heuristic, but good enough.
    elasticlunr.tokenizer.setSeperator(/[\s\-.;&_'"=,()]+|<[^>]*>/);

    let searchIndex;
    if (docs._isPrebuiltIndex) {
        console.info("using precompiled search index");
        searchIndex = elasticlunr.Index.load(docs);
    } else {
        console.time("building search index");
        // mirrored in build-search-index.js (part 2)
        searchIndex = elasticlunr(function () {
            this.pipeline.remove(elasticlunr.stemmer);
            this.pipeline.remove(elasticlunr.stopWordFilter);
            this.addField("qualname");
            this.addField("fullname");
            this.addField("annotation");
            this.addField("default_value");
            this.addField("signature");
            this.addField("bases");
            this.addField("doc");
            this.setRef("fullname");
        });
        for (let doc of docs) {
            searchIndex.addDoc(doc);
        }
        console.timeEnd("building search index");
    }

    return (term) => searchIndex.search(term, {
        fields: {
            qualname: {boost: 4},
            fullname: {boost: 2},
            annotation: {boost: 2},
            default_value: {boost: 2},
            signature: {boost: 2},
            bases: {boost: 2},
            doc: {boost: 1},
        },
        expand: true
    });
